local config = {
  ui_story_5079_50790100_1_dialog_content = "<color=#e8d9bb>Clickety-clack, clickety-clack—</color>",
  ui_story_5079_50790100_2_dialog_content = "Pact?",
  ui_story_5079_50790100_3_dialog_content = "<color=#e8d9bb>Clickety-clack, clickety-clack—</color>",
  ui_story_5079_50790100_4_dialog_content = "... Hmm?",
  ui_story_5079_50790100_5_dialog_content = "\"Hmm\"? At a time like this, is that truly all you have to say? Please explain yourself right this instant.",
  ui_story_5079_50790100_6_dialog_content = "Ah...",
  ui_story_5079_50790100_7_dialog_content = "Don't get the wrong idea—I'm not here to steal your White Suitcase. I just came to take out some money that I left in there.",
  ui_story_5079_50790100_8_dialog_content = "... How many times have I told you not to put things inside my White Suitcase? Do you have any idea how difficult it is to make it spit them back out?",
  ui_story_5079_50790100_9_dialog_content = "If you come to extort money from me, the least you can do is think of a better excuse.",
  ui_story_5079_50790100_10_dialog_content = "\"Extort\"? I would never do something so improper! I just couldn't think of a safer place to store my money, that's all...",
  ui_story_5079_50790100_11_dialog_content = "Ask your White Suitcase if you don't believe me! You can communicate with it, right?",
  ui_story_5079_50790100_12_dialog_content = "... Forget it. Now is not the best time for you to make a \"withdrawal\" from White Suitcase.",
  ui_story_5079_50790100_13_dialog_content = "Here, is this enough for you?",
  ui_story_5079_50790100_14_dialog_content = "Are you trying to insult me? What is this pittance?",
  ui_story_5079_50790100_15_dialog_content = "Then how about this? Still think it's a pittance?",
  ui_story_5079_50790100_16_dialog_content = "It's still not enough.",
  ui_story_5079_50790100_17_dialog_content = "Then here, but this is the last of it. Any more and I'll begin to suspect your motives.",
  ui_story_5079_50790100_18_dialog_content = "Can we stop beating around the bush already? Just give me all the money you're carrying right now, and we can be done here.",
  ui_story_5079_50790100_19_dialog_content = "All of it? Are you finally blinded by evil and thus require an exorbitant amount of money to carry out your wicked deeds?",
  ui_story_5079_50790100_20_dialog_content = "What are you talking about? I just need money to buy ingredients for our <color=#FFB400>banquet</color>!",
  ui_story_5079_50790100_21_dialog_content = "I hardly get the chance to take responsibility for something like this. It's the perfect opportunity...",
  ui_story_5079_50790100_22_dialog_content = "I can show you all what it means to execute a mission flawlessly. That way, people will stop treating me like a side character.",
  ui_story_5079_50790100_23_dialog_content = "You're procuring ingredients for our <color=#FFB400>banquet</color>? And you think you can accomplish such an important task with your paltry savings?",
  ui_story_5079_50790100_24_dialog_content = "Humph! Trust me, I have a few tricks up my sleeve. Now hand over all your money!",
  ui_story_5079_50790100_25_dialog_content = "Very well, but if I fail to reclaim the same amount from inside my White Suitcase, I'll—",
  ui_story_5079_50790100_26_dialog_content = "Yeah, yeah, I know!",
  ui_story_5079_50790100_27_dialog_content = "Heheheh, just you wait! This next banquet will knock everybody's socks off!",
  ui_story_5079_50790100_28_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790100_29_dialog_content = "Urgh... My head...",
  ui_story_5079_50790100_30_dialog_content = "Did I accidentally doze off? My dream felt so long too... But what was it about?",
  ui_story_5079_50790100_31_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790100_32_dialog_content = "Wait... Am I on a train?",
  ui_story_5079_50790100_33_dialog_content = "Rats! I don't think I have enough time to buy new clothes—",
  ui_story_5079_50790100_34_dialog_content = "Huh? Wait, my clothes...",
  ui_story_5079_50790100_35_dialog_content = "Heh, guess I wasn't completely awake just now. It looks like I already changed my outfit.",
  ui_story_5079_50790100_36_dialog_content = "Before conducting any sort of business, making yourself look dignified and presentable is the most important thing you can do.",
  ui_story_5079_50790100_37_dialog_content = "Only by doing so will rich customers give you their time and their patronage.",
  ui_story_5079_50790100_38_dialog_content = "That's what he said... all those years ago.",
  ui_story_5079_50790100_39_dialog_content = "Even though I can barely remember what he looks like, his nagging still buzzes around in my head...",
  ui_story_5079_50790100_40_dialog_content = "Anyway, I can't help but trust him when it comes to doing business.",
  ui_story_5079_50790100_41_dialog_content = "After all, he might've become a powerful merchant back then if it hadn't been for me... Heh.",
  ui_story_5079_50790100_42_dialog_content = "<color=#e8d9bb>The train is now arriving at <color=#FFB400>Folta Town</color>.</color>",
  ui_story_5079_50790100_43_dialog_content = "Folta... a town famous for its wholesale food markets. I'm finally almost there, huh?",
  ui_story_5079_50790100_44_dialog_content = "I bet those lazy jerks never bothered coming all the way out here for ingredients!",
  ui_story_5079_50790100_45_dialog_content = "Still, I should thank them for setting the bar so low. It just means I'll outshine them even more when I finish this.",
  ui_story_5079_50790100_46_dialog_content = "I might even get my wish if I do this right, and I won't have to work for that thing anymore...",
  ui_story_5079_50790100_47_dialog_content = "You've done well, Pact. As a reward, I will grant you one wish.",
  ui_story_5079_50790100_48_dialog_content = "If I remember correctly, your original wish... was to get rid of Hunting Stone, yes?",
  ui_story_5079_50790100_49_dialog_content = "When you have made your decision, come find me.",
  ui_story_5079_50790100_50_dialog_content = "My goodness, Pact! I'm amazed you managed to gather such prime ingredients for our banquet.",
  ui_story_5079_50790100_51_dialog_content = "In fact... I could never accomplish such a feat for myself.",
  ui_story_5079_50790100_52_dialog_content = "Please, you must teach me your ways.",
  ui_story_5079_50790100_53_dialog_content = "Heheh... Heheheheh...",
  ui_story_5079_50790100_54_dialog_content = "Pardon me, miss, but it seems you forgot your luggage.",
  ui_story_5079_50790100_55_dialog_content = "Huh? I think you're mistaking me for some other passenger. I'm not the type of person who misplaces their belongings.",
  ui_story_5079_50790100_56_dialog_content = "I'm sorry, it's just that the luggage strongly matches your outfit, so I assumed it belonged to you.",
  ui_story_5079_50790100_57_dialog_content = "...",
  ui_story_5079_50790100_58_dialog_content = "Oh, you mean Hunting Stone? Don't worry, it follows me around wherever I go. I can't get rid of it even if I want to.",
  ui_story_5079_50790100_59_dialog_content = "I'm surprised you were not scared by it though. That's quite rare.",
  ui_story_5079_50790100_60_dialog_content = "Scared? Of course not! I actually find it quite charming.",
  ui_story_5079_50790100_61_dialog_content = "(Seems like this conductor is pretty open-minded. I can't count how many times people have shunned me because of Hunting Stone.)",
  ui_story_5079_50790100_62_dialog_content = "(Even those clothing stores claiming \"customer first\" wouldn't give me the time of day...)",
  ui_story_5079_50790100_63_dialog_content = "E-Excuse me, but... wh-what on earth is that thing behind you?",
  ui_story_5079_50790100_64_dialog_content = "Perhaps it's best if you try another store, miss. While you can certainly afford our clothing, I'm afraid we cannot afford to lose customers because of your... companion.",
  ui_story_5079_50790100_65_dialog_content = "There's no need to offer more money, miss...",
  ui_story_5079_50790100_66_dialog_content = "Might I make a suggestion? If you don't mind, why not buy something to make your friend look... a bit less intimidating?",
  ui_story_5079_50790100_67_dialog_content = "Otherwise, I fear it will spoil the look of your outfit, and your money will be ill-spent...",
  ui_story_5079_50790100_68_dialog_content = "You say it's called Hunting Stone? What a magnificent name! My train, Other End, has an equally impressive name as well.",
  ui_story_5079_50790100_69_dialog_content = "I don't recall asking for your train's name...",
  ui_story_5079_50790100_70_dialog_content = "I can see that your Hunting Stone is much like my Other End, in that they occupy similar places in our hearts.",
  ui_story_5079_50790100_71_dialog_content = "Then you might have to get your eyes checked, unless you want to ditch this train as well. To me, Hunting Stone... is nothing but a pain.",
  ui_story_5079_50790100_72_dialog_content = "Hahaha! I would never abandon my old buddy, and something tells me... neither would you. Till next time we meet, milady.",
  ui_story_5079_50790100_73_dialog_content = "What the heck was he going on about?",
  ui_story_5079_50790100_74_dialog_content = "Listen up, Hunting Stone. I know you don't understand how much money I spent on these decorations for you...",
  ui_story_5079_50790100_75_dialog_content = "But you have to promise not to scare anyone. This mission means everything to me!",
  ui_story_5079_50790100_76_dialog_content = "!",
  ui_story_5079_50790100_77_dialog_content = "Good! Since we're on the same page now, you can stop moving faster than me—",
  ui_story_5079_50790100_78_dialog_content = "Wh-What is this thing?",
  ui_story_5079_50790100_79_dialog_content = "... Great. We haven't even gotten off the train, and we're already scaring people.",
  ui_story_5079_50790100_80_dialog_content = "Something so elegant must belong to quite an important person...",
  ui_story_5079_50790100_81_dialog_content = "Ahem... Sorry about that. I'll get it out of here right now.",
  ui_story_5079_50790100_82_dialog_content = "You? Tell me, are you one of the wealthy elites of Lumopolis, or perhaps Umbraton?",
  ui_story_5079_50790100_83_dialog_content = "Please excuse my rudeness just now! I meant nothing by it...",
  ui_story_5079_50790100_84_dialog_content = "Why are you apologizing? I'm the one in your way, aren't I?",
  ui_story_5079_50790100_85_dialog_content = "I'm honored to have shared this train with you today, my lady. Safe travels...",
  ui_story_5079_50790100_86_dialog_content = "Th-Thanks.",
  ui_story_5079_50790100_87_dialog_content = "So weird... What was up with that guy just now? Are these clothes magical or something?",
  ui_story_5079_50790100_88_dialog_content = "And why does it feel like I've seen him somewhere before?",
  ui_story_5079_50790100_89_dialog_content = "Ah, forget it. Now's not the time to worry about these things...",
  ui_story_5079_50790100_90_dialog_content = "*sniffs*",
  ui_story_5079_50790100_91_dialog_content = "Wow, those smells... Beef and tomatoes! Cream cookies and fresh-baked bread! And more...",
  ui_story_5079_50790100_92_dialog_content = "That's Folta for you! We haven't even left the train, and I can already smell so much wonderful food!",
  ui_story_5079_50790100_93_dialog_content = "Looks like we'll have to sample a few local dishes before getting down to business!",
  ui_story_5079_50790100_94_dialog_content = "!",
  ui_story_5079_50790200_1_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5079_50790200_2_dialog_content = "So this is Folta!",
  ui_story_5079_50790200_3_dialog_content = "The architecture is so unique. This place looks like it's much more obsessed with food than Umbraton!",
  ui_story_5079_50790200_4_dialog_content = "Huh? Could it be that these houses are made out of actual ingredients?",
  ui_story_5079_50790200_5_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790200_6_dialog_content = "Ah... I'm gonna miss the train! Excuse me!",
  ui_story_5079_50790200_7_dialog_content = "Eh?",
  ui_story_5079_50790200_8_dialog_content = "<color=#e8d9bb>Wham!</color>",
  ui_story_5079_50790200_9_dialog_content = "Ouch...",
  ui_story_5079_50790200_10_dialog_content = "I just bought these clothes too! I bet they're filthy now!",
  ui_story_5079_50790200_11_dialog_content = "Huh? They're not dirty at all. In fact, they're giving off a sweet aroma... Wait, are these rocks on the ground made of candy?",
  ui_story_5079_50790200_12_dialog_content = "...",
  ui_story_5079_50790200_13_dialog_content = "I wonder what they taste like? I usually eat Lumopolis rocks to help with digestion, so one little bite shouldn't hurt...",
  ui_story_5079_50790200_14_dialog_content = "Ah!",
  ui_story_5079_50790200_15_dialog_content = "Huh?",
  ui_story_5079_50790200_16_dialog_content = "What do you think you're doing, miss? These stones aren't for eating!",
  ui_story_5079_50790200_17_dialog_content = "Heh, say you... Besides, who are you to tell me I can't eat them?",
  ui_story_5079_50790200_18_dialog_content = "You don't seem to understand, which means you're probably not from around here.",
  ui_story_5079_50790200_19_dialog_content = "These stones are fodder for <color=#FFB400>candy sparrows</color>. It's because of their help that we can construct our buildings out of food!",
  ui_story_5079_50790200_20_dialog_content = "How could you think of depriving such hard-working creatures of their food?",
  ui_story_5079_50790200_21_dialog_content = "So you're saying all the buildings here really are made out of food?",
  ui_story_5079_50790200_22_dialog_content = "Uh-huh! Just take a look around—the floorboards are made of cocoa beans, and the streetlamps are glowing lollipops, and...",
  ui_story_5079_50790200_23_dialog_content = "Hey! What are you doing to that streetlamp?",
  ui_story_5079_50790200_24_dialog_content = "The penalty for damaging public property is serious! They'll dangle you in the street and let candy sparrows peck you to pieces...",
  ui_story_5079_50790200_25_dialog_content = "Don't you know anything about this place?",
  ui_story_5079_50790200_26_dialog_content = "Sounds like a bunch of baloney to me. Are you sure you're not just making it all up?",
  ui_story_5079_50790200_27_dialog_content = "Are you kidding? That's the whole reason Folta's streets are so clean and tidy!",
  ui_story_5079_50790200_28_dialog_content = "You know, miss... Even though you're wearing such sophisticated clothes, you're acting no different than a little kid.",
  ui_story_5079_50790200_29_dialog_content = "Guess my father was lying when he said that well-dressed people conduct themselves better than others!",
  ui_story_5079_50790200_30_dialog_content = "Say... You didn't steal that outfit, did you? Did you?",
  ui_story_5079_50790200_31_dialog_content = "Hah? I'll have you know I spent a fortune on these clothes...",
  ui_story_5079_50790200_32_dialog_content = "(Humph, I don't have to sit here and take this from a little girl.)",
  ui_story_5079_50790200_33_dialog_content = "(She has no respect for her elders, or boundaries for that matter... But for some reason, her annoying attitude is strangely familiar.)",
  ui_story_5079_50790200_34_dialog_content = "Hmm... I feel like bumping into this weird lady made me forget something...",
  ui_story_5079_50790200_35_dialog_content = "<color=#e8d9bb>Choooooo—</color>",
  ui_story_5079_50790200_36_dialog_content = "Oh crud, the train! It left!",
  ui_story_5079_50790200_37_dialog_content = "This is all your fault! First you bumped into me, then you wasted all my time with your shenanigans, and finally I missed the train!",
  ui_story_5079_50790200_38_dialog_content = "My plan to run away from home is ruined! I hope you're ready to make it up to me!",
  ui_story_5079_50790200_39_dialog_content = "Huh? You were running away? And what do you mean by \"make it up to me\"?",
  ui_story_5079_50790200_40_dialog_content = "You're the one who ran into me... If anything, you should be making it up to me!",
  ui_story_5079_50790200_41_dialog_content = "What's more, I just did you a huge favor by foiling your little plan to run away. Some gratitude would be nice, don't you think?",
  ui_story_5079_50790200_42_dialog_content = "Huh? You're dreaming if you think I should be thanking you! Besides, you would've gotten pecked to shreds if it hadn't been for me!",
  ui_story_5079_50790200_43_dialog_content = "If anyone should be grateful here, it's you!",
  ui_story_5079_50790200_44_dialog_content = "Don't get the wrong idea, kid! I only did that because I was researching ingredients!",
  ui_story_5079_50790200_45_dialog_content = "You didn't think I was gonna eat rocks just because I was hungry, did you? Did you?",
  ui_story_5079_50790200_46_dialog_content = "And now you're copying me! Urgh... You really are immature, you know that?",
  ui_story_5079_50790200_47_dialog_content = "I'm done bickering with this kid. I have tons of shopping to do, and I still need to visit plenty of shops and compare their prices.",
  ui_story_5079_50790200_48_dialog_content = "... H-Hang on!",
  ui_story_5079_50790200_49_dialog_content = "What now?",
  ui_story_5079_50790200_50_dialog_content = "You're here to buy ingredients, right? That's what my family's business is all about! Would you like to come to our shop?",
  ui_story_5079_50790200_51_dialog_content = "Now you want my business after all that arguing? Sorry, but I'm not interested.",
  ui_story_5079_50790200_52_dialog_content = "<size=30>*sigh* Another failure...</size>",
  ui_story_5079_50790200_53_dialog_content = "(Father always says we can't afford to give up on chances to make deals with wealthy customers like her...)",
  ui_story_5079_50790200_54_dialog_content = "(If I can get her to come to our shop... I bet father will praise me lots! Maybe he'll forget all about what happened these last few days too.)",
  ui_story_5079_50790200_55_dialog_content = "(But most importantly, I can use this as a chance to get rid of all the stuff I don't like to eat... Heeheehee!)",
  ui_story_5079_50790200_56_dialog_content = "I-I could always ask my father to give you an incredible discount! Think of it as my way making it up to you!",
  ui_story_5079_50790200_57_dialog_content = "Weren't you trying to run away from home? Why would you bring a stranger home and ask for a discount?",
  ui_story_5079_50790200_58_dialog_content = "If I were your father, I would never agree to anything like that.",
  ui_story_5079_50790200_59_dialog_content = "*sniffles* Wh-What should I do?",
  ui_story_5079_50790200_60_dialog_content = "I got it! I'll tell him that you were worried about my safety, so you brought me home! He'll be so grateful that he'll offer you a once-in-a-lifetime deal!",
  ui_story_5079_50790200_61_dialog_content = "That does make sense... I suppose one good deed couldn't hurt.",
  ui_story_5079_50790200_62_dialog_content = "Just remember, I can't promise that I'll do business with your family. Lead the way, kid.",
  ui_story_5079_50790200_63_dialog_content = "Huh? What's that thing behind you?",
  ui_story_5079_50790200_64_dialog_content = "You finally noticed, huh? It's not too late to be scared, you know! Especially now that you know what will happen if you make me mad...",
  ui_story_5079_50790200_65_dialog_content = "Wow, it's so cute! And look, it can move on its own! Can I pet it? Can I?",
  ui_story_5079_50790200_66_dialog_content = "Hey, knock that off! This isn't a toy!",
  ui_story_5079_50790200_67_dialog_content = "Why are you getting so upset? I just wanted to pet your little friend...",
  ui_story_5079_50790200_68_dialog_content = "My \"little friend\"? You think Hunting Stone is... Urgh, forget it.",
  ui_story_5079_50790200_69_dialog_content = "Knock yourself out, kid, but you're gonna give me an even bigger discount for each time you pet it.",
  ui_story_5079_50790200_70_dialog_content = "O-Okay then... I'll just pet it once...",
  ui_story_5079_50790200_71_dialog_content = "!",
  ui_story_5079_50790200_72_dialog_content = "Wow, it's so adorable! It snuggled up to me, so those last few pets don't count!",
  ui_story_5079_50790200_73_dialog_content = "!",
  ui_story_5079_50790200_74_dialog_content = "(Hunting Stone let her touch it? Why, you good-for-nothing wheel!)",
  ui_story_5079_50790200_75_dialog_content = "Alright, that's enough! Let's get going!",
  ui_story_5079_50790300_1_dialog_content = "Hmm, hmm, hmm!",
  ui_story_5079_50790300_2_dialog_content = "... What are you so happy about?",
  ui_story_5079_50790300_3_dialog_content = "You're the first big customer I've ever brought home, so of course I'm happy! Father's gonna be so pleased with me!",
  ui_story_5079_50790300_4_dialog_content = "Do you usually help out with your family's business?",
  ui_story_5079_50790300_5_dialog_content = "Yeah... But I usually just get in the way. In fact, I think I'm the reason our shop's doing so poorly these days.",
  ui_story_5079_50790300_6_dialog_content = "But now that you're here, things might finally turn around for us!",
  ui_story_5079_50790300_7_dialog_content = "... I don't even know your name, kid.",
  ui_story_5079_50790300_8_dialog_content = "Me?",
  ui_story_5079_50790300_9_dialog_content = "Huh?",
  ui_story_5079_50790300_10_dialog_content = "My name is... <color=#FFB400>Popo</color>.",
  ui_story_5079_50790300_11_dialog_content = "Ah, don't get any crazy ideas! It's just a name! A perfectly normal name!",
  ui_story_5079_50790300_12_dialog_content = "I wasn't going to give it a second thought, but since you made such a big deal about it, now I kind of want to ask...",
  ui_story_5079_50790300_13_dialog_content = "It's a pretty cute name, you know.",
  ui_story_5079_50790300_14_dialog_content = "Alright, that's enough! We're not here to discuss the cuteness of names, now let's go!",
  ui_story_5079_50790300_15_dialog_content = "This is the place!",
  ui_story_5079_50790300_16_dialog_content = "Really? It doesn't look like it's open for business...",
  ui_story_5079_50790300_17_dialog_content = "Hmm... Father? Are you home?",
  ui_story_5079_50790300_18_dialog_content = "Well, I don't mean to be rude, but there's a \"closed\" sign posted on the door.",
  ui_story_5079_50790300_19_dialog_content = "Your shop hasn't been open for a while, it seems. Weren't you aware of that?",
  ui_story_5079_50790300_20_dialog_content = "?",
  ui_story_5079_50790300_21_dialog_content = "I have no idea what you're talking about!",
  ui_story_5079_50790300_22_dialog_content = "My father loves his store, and he keeps it open every day of the year! How could it be closed?",
  ui_story_5079_50790300_23_dialog_content = "Why don't you take a look for yourself? It says here, \"Shop closed due to family reasons.\"",
  ui_story_5079_50790300_24_dialog_content = "(I knew I shouldn't have gotten involved with this kid. I've already wasted so much time.)",
  ui_story_5079_50790300_25_dialog_content = "(If I don't pull this off perfectly, who knows how badly they're gonna make fun of me...)",
  ui_story_5079_50790300_26_dialog_content = "Sorry, Popo, but I can't do business with your family if there's no business at all. I should get—",
  ui_story_5079_50790300_27_dialog_content = "*sobbing*... <size=45>Waaaaaaaaahhh!</size>",
  ui_story_5079_50790300_28_dialog_content = "Hey, don't cry! People are gonna think I'm picking on you!",
  ui_story_5079_50790300_29_dialog_content = "That's because you ARE picking on me!",
  ui_story_5079_50790300_30_dialog_content = "If I hadn't missed my train, I'd have been long gone by now! Then I'd never have found out that my father really doesn't want me anymore!",
  ui_story_5079_50790300_31_dialog_content = "But still, crying won't solve anything. Do you have anyone else to rely on besides your father?",
  ui_story_5079_50790300_32_dialog_content = "No... My mother passed away a long time ago. Father and I have been taking care of each other ever since...",
  ui_story_5079_50790300_33_dialog_content = "But we argue all the time... And during our last fight, he said he had no need for a disobedient daughter like me.",
  ui_story_5079_50790300_34_dialog_content = "I was furious with him too! So furious that I ran away from home...",
  ui_story_5079_50790300_35_dialog_content = "I had no idea he would actually leave... Father really doesn't love me anymore... Waaaaah!",
  ui_story_5079_50790300_36_dialog_content = "But it's normal to argue with your dad, isn't it?",
  ui_story_5079_50790300_37_dialog_content = "*sniffs*... Does that mean you argue with your father too?",
  ui_story_5079_50790300_38_dialog_content = "I did, and it was pretty bad too. He refused to accept me or my Hunting Stone here—the one you think is so cute.",
  ui_story_5079_50790300_39_dialog_content = "...",
  ui_story_5079_50790300_40_dialog_content = "So he left me some money, and then I never saw him again...",
  ui_story_5079_50790300_41_dialog_content = "Huh? You mean your father actually left you some money?",
  ui_story_5079_50790300_42_dialog_content = "But my father didn't leave me anything before abandoning me!",
  ui_story_5079_50790300_43_dialog_content = "<size=50>Waaaaaaaaaah!</size>",
  ui_story_5079_50790300_44_dialog_content = "Don't say that, Popo! Your father left you this store, didn't he?",
  ui_story_5079_50790300_45_dialog_content = "I'm pretty sure that makes you the boss around here, right? If so, could I buy this chocolate table from you? I'm pretty hungry!",
  ui_story_5079_50790300_46_dialog_content = "It looks a little hard, but I bet it tastes great. Look, it even has a layer of frosting on top!",
  ui_story_5079_50790300_47_dialog_content = "Oh? Is the glass on that cabinet made from caramelized brown sugar?",
  ui_story_5079_50790300_48_dialog_content = "And that vase is actually a honey jar! Can I dip this in honey? The vase looks pretty tasty too...",
  ui_story_5079_50790300_49_dialog_content = "Ahhhh! Stop trying to eat the furniture! This is still my house, you know!",
  ui_story_5079_50790300_50_dialog_content = "You really have no manners at all, or taste for that matter!",
  ui_story_5079_50790300_51_dialog_content = "I mean, what kind of person dips hard candy in honey? Are you trying to rot your teeth?",
  ui_story_5079_50790300_52_dialog_content = "Oh good, you're not crying anymore.",
  ui_story_5079_50790300_53_dialog_content = "Huh? You were trying to cheer me up?",
  ui_story_5079_50790300_54_dialog_content = "Nope, I'm just really, really hungry.",
  ui_story_5079_50790300_55_dialog_content = "Well... That's still no excuse for you to eat our furniture!",
  ui_story_5079_50790300_56_dialog_content = "We still have plenty of carrots in stock, so help yourself to those.",
  ui_story_5079_50790300_57_dialog_content = "Carrots? Yuck...",
  ui_story_5079_50790300_58_dialog_content = "What? You don't like carrots either?",
  ui_story_5079_50790300_59_dialog_content = "That doesn't even come close to describing my hatred for them... Carrots are the scariest food in the world!",
  ui_story_5079_50790300_60_dialog_content = "I know! I know!",
  ui_story_5079_50790300_61_dialog_content = "Carrots shouldn't even exist in this world! They were the whole reason I got into that fight with my father!",
  ui_story_5079_50790300_62_dialog_content = "He said it was unacceptable for the daughter of a carrot vendor to hate eating carrots, and that I was bringing shame to our family's business...",
  ui_story_5079_50790300_63_dialog_content = "But there's no rule saying that I have to like carrots just because my father sells them for a living!",
  ui_story_5079_50790300_64_dialog_content = "Heh, I didn't expect to completely agree with you on anything, but here we are.",
  ui_story_5079_50790300_65_dialog_content = "You were planning to sell all of your family's carrots to me, so you wouldn't have to eat them, huh?",
  ui_story_5079_50790300_66_dialog_content = "Well no... I was only going to sell half of them and leave the rest for my father, since he likes them so much.",
  ui_story_5079_50790300_67_dialog_content = "He does, huh... No wonder he named you \"Popo\"! I bet it's because he wanted you to love carrots too!",
  ui_story_5079_50790300_68_dialog_content = "Humph! There's nothing wrong with disliking carrots! He could've named me \"Carrot,\" and I'd still think they're gross!",
  ui_story_5079_50790300_69_dialog_content = "So even after everything that's happened, you still want to leave your father some carrots to eat?",
  ui_story_5079_50790300_70_dialog_content = "Ah... That was my idea from before, but not anymore! I'm getting rid of all these stinkin' carrots now!",
  ui_story_5079_50790300_71_dialog_content = "Do you still love your father?",
  ui_story_5079_50790300_72_dialog_content = "O-Of course I don't! Why would I care about him after he abandoned me like this? Humph!",
  ui_story_5079_50790300_73_dialog_content = "But what if he didn't actually abandon you?",
  ui_story_5079_50790300_74_dialog_content = "Well, uh... We'd just have to wait and see!",
  ui_story_5079_50790300_75_dialog_content = "(Little kids are way too predictable... I don't think her father's as mean as she says.)",
  ui_story_5079_50790300_76_dialog_content = "(He's probably just trying to force his preferences on his daughter, which is why they fight so much. It's a mistake, but one he makes out of love.)",
  ui_story_5079_50790300_77_dialog_content = "(A tiny gap like that is easy enough to bridge.)",
  ui_story_5079_50790300_78_dialog_content = "It looks like your problems with your father are pretty small, at least compared to my own.",
  ui_story_5079_50790300_79_dialog_content = "One time, when my father tried to force me to eat carrots, I ate a handful of rocks just to get back at him...",
  ui_story_5079_50790300_80_dialog_content = "Oh! So that's why you were so ready to eat those rocks earlier!",
  ui_story_5079_50790300_81_dialog_content = "It had nothing to do with you being immature or having no taste at all!",
  ui_story_5079_50790300_82_dialog_content = "... Would it kill you to be more polite once in a while? Remember, you're the one who owes me!",
  ui_story_5079_50790400_1_dialog_content = "Feeling better yet? You should, after all that chatting...",
  ui_story_5079_50790400_2_dialog_content = "Just remember, every dark cloud has a silver lining. We may have been abandoned, but at least we're free now.",
  ui_story_5079_50790400_3_dialog_content = "And if my father hadn't left me, I would never have met... Never mind, you're still too young to know about that.",
  ui_story_5079_50790400_4_dialog_content = "I don't care about that!",
  ui_story_5079_50790400_5_dialog_content = "I'm not gonna take this lying down! I'm getting my revenge on father!",
  ui_story_5079_50790400_6_dialog_content = "Think I could borrow your wheel for a bit? I wanna use it to run him over a few times!",
  ui_story_5079_50790400_7_dialog_content = "...",
  ui_story_5079_50790400_8_dialog_content = "... I told you, it's called Hunting Stone.",
  ui_story_5079_50790400_9_dialog_content = "And while I'd love to lend it to you... it refuses to leave my side, ever.",
  ui_story_5079_50790400_10_dialog_content = "Besides, you shouldn't get so worked up about this, Popo. Something tells me that your father didn't actually abandon you.",
  ui_story_5079_50790400_11_dialog_content = "But I told you all about what happened...",
  ui_story_5079_50790400_12_dialog_content = "Yes, after seeing the shop and giving it some thought, I think I have a good idea about what's going on.",
  ui_story_5079_50790400_13_dialog_content = "See? The carrots in these piles are clearly still fresh. That tells me they just came in, and he was getting ready to sell them.",
  ui_story_5079_50790400_14_dialog_content = "Also, none of the valuables in your house are missing. That's not something I would do if I was planning to leave.",
  ui_story_5079_50790400_15_dialog_content = "He wouldn't leave all of his possessions lying around like this unless...",
  ui_story_5079_50790400_16_dialog_content = "Unless?",
  ui_story_5079_50790400_17_dialog_content = "Unless he had so much debt that he couldn't pay it all back. He can avoid suspicion and escape much more easily if he leaves everything exactly where it is.",
  ui_story_5079_50790400_18_dialog_content = "Oh...",
  ui_story_5079_50790400_19_dialog_content = "Wh-What's with that look?",
  ui_story_5079_50790400_20_dialog_content = "For someone as immature as you, I had no idea you could be so rational!",
  ui_story_5079_50790400_21_dialog_content = "Still calling me immature, huh...",
  ui_story_5079_50790400_22_dialog_content = "Let's just drop it. Arguing about it just makes us both immature.",
  ui_story_5079_50790400_23_dialog_content = "But now that you mention it...",
  ui_story_5079_50790400_24_dialog_content = "I'm pretty sure my father actually borrowed money from... the <color=#FFB400>Ketchup Family</color>!",
  ui_story_5079_50790400_25_dialog_content = "But that debt should've been repaid a long time ago! Could father have borrowed more money without telling me?",
  ui_story_5079_50790400_26_dialog_content = "I hardly think your father has any need to tell you about his debts...",
  ui_story_5079_50790400_27_dialog_content = "That's it! I've made my decision!",
  ui_story_5079_50790400_28_dialog_content = "Great... And what brilliant decision would that be?",
  ui_story_5079_50790400_29_dialog_content = "I'm going to pay a visit to the Ketchup Family! They might even know where my father is right now!",
  ui_story_5079_50790400_30_dialog_content = "Oh? That's actually a pretty good idea.",
  ui_story_5079_50790400_31_dialog_content = "(I can finally stop babysitting this kid now...)",
  ui_story_5079_50790400_32_dialog_content = "I hope the Ketchup Family has the answers you're looking for, kid. Now then, I should really be...",
  ui_story_5079_50790400_33_dialog_content = "W-Wait! You can't leave yet!",
  ui_story_5079_50790400_34_dialog_content = "Huh?",
  ui_story_5079_50790400_35_dialog_content = "Heheh, there's a reason I keep calling you immature, you know?",
  ui_story_5079_50790400_36_dialog_content = "If you leave right now, you're gonna regret it for the rest of your life!",
  ui_story_5079_50790400_37_dialog_content = "And why is that?",
  ui_story_5079_50790400_38_dialog_content = "The Ketchup Family has always been in charge of this town. They also run the biggest tomato store in all of Astra!",
  ui_story_5079_50790400_39_dialog_content = "If you're looking for the best ingredients, you can't afford to miss them!",
  ui_story_5079_50790400_40_dialog_content = "You must have done your research before coming to Folta, haven't you? Haven't you?",
  ui_story_5079_50790400_41_dialog_content = "We have an old saying around here: \"Anyone who comes to Folta without doing business with the Ketchup Family is a fool!\"",
  ui_story_5079_50790400_42_dialog_content = "You sure you're not just making that \"old saying\" up, kid?",
  ui_story_5079_50790400_43_dialog_content = "Anyway, I'm feeling pretty generous today! Come with me, and I'll personally introduce you to the Ketchup Family!",
  ui_story_5079_50790400_44_dialog_content = "\"Generous,\" eh? You're just too scared to see them on your own, aren't you?",
  ui_story_5079_50790400_45_dialog_content = "After all, I'm sure a wealthy family like that has no time for little kids like you...",
  ui_story_5079_50790400_46_dialog_content = "And you thought you were ready to run away from home...",
  ui_story_5079_50790400_47_dialog_content = "Th-That's not it at all! I-I'm only doing this for your sake...",
  ui_story_5079_50790400_48_dialog_content = "Humph, well, you can forget all about it now! Enjoy being a fool, lady, and I'm gonna go see them all by myself!",
  ui_story_5079_50790400_49_dialog_content = "So now I'm immature AND a fool...",
  ui_story_5079_50790400_50_dialog_content = "Tsk! Rude little punks like her just have to learn things the hard way.",
  ui_story_5079_50790400_51_dialog_content = "Urgh, but why am I so uneasy?",
  ui_story_5079_50790400_52_dialog_content = "If she wasn't lying about the Ketchup Family, then I definitely have to pay them a visit.",
  ui_story_5079_50790400_53_dialog_content = "Besides, I'm not sure Popo will get very far with that temper of hers. If anything happens to her...",
  ui_story_5079_50790400_54_dialog_content = "I'm not actually worried about her or anything... but lots of people saw us together earlier.",
  ui_story_5079_50790400_55_dialog_content = "If something happens to her, every single person in this podunk town is gonna come after me, since I'm an outsider...",
  ui_story_5079_50790400_56_dialog_content = "Hey Popo! Wait up!",
  ui_story_5079_50790400_57_dialog_content = "Humph! Do I know you?",
  ui_story_5079_50790400_58_dialog_content = "I happen to be going this way too. Wanna walk together?",
  ui_story_5079_50790400_59_dialog_content = "No!",
  ui_story_5079_50790400_60_dialog_content = "Although... If you beg me to let you walk with me, I might reconsider.",
  ui_story_5079_50790400_61_dialog_content = "Like I said, I just happen to be going in the same direction...",
  ui_story_5079_50790400_62_dialog_content = "How about this? You walk together with me, and I'll help you ask the Ketchup Family about your father.",
  ui_story_5079_50790400_63_dialog_content = "You're a pretty smart girl, so I'm sure you'll make the right choice.",
  ui_story_5079_50790400_64_dialog_content = "Hmm...",
  ui_story_5079_50790400_65_dialog_content = "Alright, but you have to walk behind me the whole time!",
  ui_story_5079_50790400_66_dialog_content = "And don't get lost! I don't feel like looking for you if you do!",
  ui_story_5079_50790400_67_dialog_content = "(Kids are such a huge pain...)",
  ui_story_5079_50790400_68_dialog_content = "Fine, let's go.",
  ui_story_5079_50790500_1_dialog_content = "W-Well... H-Here we are! L-Let's go inside!",
  ui_story_5079_50790500_2_dialog_content = "Are you okay? You're stuttering a lot... You're not nervous, are you?",
  ui_story_5079_50790500_3_dialog_content = "O-Of course not! I-I'm just a little excited, that's all.",
  ui_story_5079_50790500_4_dialog_content = "After all, we're meeting with the head of the Ketchup Family... I-I happen to have a lot of respect for her!",
  ui_story_5079_50790500_5_dialog_content = "But coming to her house uninvited and dressed like this... D-Do you think I'll make a bad impression on her?",
  ui_story_5079_50790500_6_dialog_content = "You worry a lot for someone your age, Popo.",
  ui_story_5079_50790500_7_dialog_content = "But you'll be fine. Just stand behind me and let me do the talking for you.",
  ui_story_5079_50790500_8_dialog_content = "Ah, I see we have a guest from afar. Welcome, my lady.",
  ui_story_5079_50790500_9_dialog_content = "I see you bring someone with you... a familiar-looking little one.",
  ui_story_5079_50790500_10_dialog_content = "I must say, you two make quite an interesting duo. Tell me, what brings you here today?",
  ui_story_5079_50790500_11_dialog_content = "I came because... Wait a minute, haven't we met before?",
  ui_story_5079_50790500_12_dialog_content = "I believe you are mistaken, my lady. While I have welcomed no shortage of guests so far...",
  ui_story_5079_50790500_13_dialog_content = "I'm certain I would remember such a beautiful and noble-looking young lady such as yourself.",
  ui_story_5079_50790500_14_dialog_content = "I-Is that so...",
  ui_story_5079_50790500_15_dialog_content = "(I knew buying these clothes was the right thing to do! Time to push my luck a little...)",
  ui_story_5079_50790500_16_dialog_content = "*stares*",
  ui_story_5079_50790500_17_dialog_content = "<size=30>I know, I know! I gave you my word, now stop looking at me like that!</size>",
  ui_story_5079_50790500_18_dialog_content = "Ahem... My reasons for coming here are twofold...",
  ui_story_5079_50790500_19_dialog_content = "One of those reasons is that this girl claims her father has abandoned her. We suspect that your family is somehow connected to this matter, so we came to inquire.",
  ui_story_5079_50790500_20_dialog_content = "... Hey! Don't be so blunt about it!",
  ui_story_5079_50790500_21_dialog_content = "This is quite a bizarre misunderstanding.",
  ui_story_5079_50790500_22_dialog_content = "Do you mean to say your father still hasn't found you, Popo?",
  ui_story_5079_50790500_23_dialog_content = "Found me?",
  ui_story_5079_50790500_24_dialog_content = "Yes. After searching everywhere for you, he concluded that you had already left on a train, so he bought a ticket for the very next outbound trip.",
  ui_story_5079_50790500_25_dialog_content = "And yet here you are. An amusing twist of fate, wouldn't you agree?",
  ui_story_5079_50790500_26_dialog_content = "Really? Really? Father only closed the shop so that he could come looking for me?",
  ui_story_5079_50790500_27_dialog_content = "Of course. Who else would look after the shop in his absence?",
  ui_story_5079_50790500_28_dialog_content = "B-B-But then...",
  ui_story_5079_50790500_29_dialog_content = "How am I supposed to find him? Who knows how far he's taking the train... I'd never have tried to run away if I had known this would happen...",
  ui_story_5079_50790500_30_dialog_content = "Don't worry, Popo.",
  ui_story_5079_50790500_31_dialog_content = "The train's conductor is part of the Ketchup Family. I'll have him tell your father to come home as soon as possible.",
  ui_story_5079_50790500_32_dialog_content = "Really? Really? Oh, thank you so much!",
  ui_story_5079_50790500_33_dialog_content = "(Phew... That's one less thing to worry about.)",
  ui_story_5079_50790500_34_dialog_content = "(Popo's father was willing to shut down his hard-earned business just to search for his daughter.)",
  ui_story_5079_50790500_35_dialog_content = "(If it were my father, humph, he'd probably feel relieved.)",
  ui_story_5079_50790500_36_dialog_content = "That reminds me, ma'am! This immature... I mean sophisticated young lady came to Folta on important business!",
  ui_story_5079_50790500_37_dialog_content = "Hey, no one asked you to butt in...",
  ui_story_5079_50790500_38_dialog_content = "She needs to buy lots of top-notch ingredients, so I thought I should bring her to see you first!",
  ui_story_5079_50790500_39_dialog_content = "You can definitely help her out, can't you?",
  ui_story_5079_50790500_40_dialog_content = "(Oh... Is this Popo's way of thanking me? I'll just let her finish then...)",
  ui_story_5079_50790500_41_dialog_content = "(Besides... I could get used to being called a \"sophisticated lady.\")",
  ui_story_5079_50790500_42_dialog_content = "Thank you, Popo. I would be more than happy to arrange something.",
  ui_story_5079_50790500_43_dialog_content = "With the Ketchup Family's standing in Folta, I can have every shop send their finest ingredients here for your selection.",
  ui_story_5079_50790500_44_dialog_content = "After such a long journey, I doubt you wish to scurry around town looking for them.",
  ui_story_5079_50790500_45_dialog_content = "And since you are kind enough to help little Popo, I can help you purchase them at the lowest possible prices. Would that be satisfactory?",
  ui_story_5079_50790500_46_dialog_content = "If it's not too much to ask, then yes, absolutely!",
  ui_story_5079_50790500_47_dialog_content = "I'll just leave my shopping list with you, ahem, thank you very much for your assistance.",
  ui_story_5079_50790500_48_dialog_content = "Think nothing of it. I'll begin gathering these items right away.",
  ui_story_5079_50790500_49_dialog_content = "Heheh!",
  ui_story_5079_50790500_50_dialog_content = "You're looking awfully smug, Popo.",
  ui_story_5079_50790500_51_dialog_content = "Well, I did just help you land a sweet deal. Hope you're ready to make it up to me afterward!",
  ui_story_5079_50790500_52_dialog_content = "I'm pretty sure I could've done it myself... never mind.",
  ui_story_5079_50790500_53_dialog_content = "The truth is, you really did help me out. How do you want me to repay you?",
  ui_story_5079_50790500_54_dialog_content = "How about sticking around until I find my father?",
  ui_story_5079_50790500_55_dialog_content = "Huh... You mean babysit you some more? Sure thing, kid.",
  ui_story_5079_50790500_56_dialog_content = "Y-You're not \"babysitting\" me! We're helping each other out, okay?",
  ui_story_5079_50790500_57_dialog_content = "And I helped you out big time, remember? You have to at least make it even!",
  ui_story_5079_50790500_58_dialog_content = "Then let me sweeten the deal with an offer you can't refuse.",
  ui_story_5079_50790500_59_dialog_content = "When your father gets back, I'll convince him to stop making you eat carrots.",
  ui_story_5079_50790500_60_dialog_content = "I'm pretty familiar with this sort of thing, especially when it comes to coaxing and pestering. It also helps that I have seventy-four reasons why carrots shouldn't be eaten.",
  ui_story_5079_50790500_61_dialog_content = "Really? That's incredible! I've only been able to come up with thirty-three reasons so far...",
  ui_story_5079_50790500_62_dialog_content = "If you actually manage to pull this off... I'll be your follower for life!",
  ui_story_5079_50790500_63_dialog_content = "Pardon me, but the lady of the house has prepared a delightful meal for our two esteemed guests. Please follow me to the dining hall, if you would.",
  ui_story_5079_50790500_64_dialog_content = "This will be the perfect opportunity for you to sample our town's different delicacies as well, milady. If you have any suggestions about the food, kindly share them with us in a respectable manner.",
  ui_story_5079_50790500_65_dialog_content = "Should you fail to demonstrate the proper level of respect towards our people, especially the head of the Ketchup Family...",
  ui_story_5079_50790500_66_dialog_content = "I may have to take action against you.",
  ui_story_5079_50790500_67_dialog_content = "I don't think you need to go that far, do you?",
  ui_story_5079_50790500_68_dialog_content = "I chose to do business with the Ketchup Family out of a sense of mutual trust.",
  ui_story_5079_50790500_69_dialog_content = "Then please forgive me for my callous insinuations... But there is a sense of unease within my heart that will not go away...",
  ui_story_5079_50790500_70_dialog_content = "In any case, right this way.",
  ui_story_5079_50790500_71_dialog_content = "Finally I get to eat! I've been wondering what Folta's food tastes like all this time...",
  ui_story_5079_50790500_72_dialog_content = "Heheh!",
  ui_story_5079_50790500_73_dialog_content = "You really don't know how to hide your emotions, do you? Remember, we're having dinner with the head of the Ketchup Family.",
  ui_story_5079_50790500_74_dialog_content = "Try to act a little more lady-like, would you?",
  ui_story_5079_50790500_75_dialog_content = "Now you're lecturing me too? You sound just as annoying as my father...",
  ui_story_5079_50790500_76_dialog_content = "Anyway, you know what dinner with the Ketchup Family means, don't you?",
  ui_story_5079_50790500_77_dialog_content = "It means everything is made with tomatoes! Which also means there won't be a single stinkin' carrot in sight!",
  ui_story_5079_50790500_78_dialog_content = "That's definitely something to look forward to, but... did I really sound like your father just now?",
  ui_story_5079_50790500_79_dialog_content = "Yeah. He always tells me how to behave at the table, not like I ever listen to him, though!",
  ui_story_5079_50790500_80_dialog_content = "You should be happy that we finally get to eat, so stop overthinking things!",
  ui_story_5079_50790500_81_dialog_content = "I know, I just...",
  ui_story_5079_50790500_82_dialog_content = "(I just don't want to turn into another stubborn grown-up like that...)",
  ui_story_5079_50790500_83_dialog_content = "Please forgive us if the meal is not as grand as expected. Our chefs made as much as they could as quickly as possible.",
  ui_story_5079_50790500_84_dialog_content = "Not to worry, all these red dishes are enough to get my appetite going!",
  ui_story_5079_50790500_85_dialog_content = "Can we eat now? Can we?",
  ui_story_5079_50790500_86_dialog_content = "Please help yourselves.",
  ui_story_5079_50790500_87_dialog_content = "I wanna try the tomato bisque first! Just thinking about that sweet and sour taste makes my mouth water!",
  ui_story_5079_50790500_88_dialog_content = "Wait, let's do it together! Three, two, one, go!",
  ui_story_5079_50790500_89_dialog_content = "Please don't make me do something so lame...",
  ui_story_5079_50790500_90_dialog_content = "Come on! Please?",
  ui_story_5079_50790500_91_dialog_content = "Fine... Three, two...",
  ui_story_5079_50790500_92_dialog_content = "One!",
  ui_story_5079_50790500_93_dialog_content = "*slurp*",
  ui_story_5079_50790500_94_dialog_content = "...",
  ui_story_5079_50790500_95_dialog_content = "...",
  ui_story_5079_50790500_96_dialog_content = "<size=45>Pfffffffft!</size>",
  ui_story_5079_50790500_97_dialog_content = "It's poisoned! The soup is poisoned! Someone's trying to do us in!",
  ui_story_5079_50790500_98_dialog_content = "This is absolutely unacceptable! Did your people do this on purpose?",
  ui_story_5079_50790500_99_dialog_content = "I refuse to believe that the Ketchup Family's cuisine is unpleasant to the point of being inedible.",
  ui_story_5079_50790500_100_dialog_content = "Are you sure you two aren't overreacting?",
  ui_story_5079_50790500_101_dialog_content = "It's not a question of taste at all! Why the heck would you people put carrots in tomato soup?",
  ui_story_5079_50790500_102_dialog_content = "Carrots? Impossible. We don't keep any such ingredients in our pantries.",
  ui_story_5079_50790500_103_dialog_content = "I'm a witness here too! Try it for yourself, ma'am!",
  ui_story_5079_50790500_104_dialog_content = "...",
  ui_story_5079_50790500_105_dialog_content = "Very well then...",
  ui_story_5079_50790500_106_dialog_content = "*sips*",
  ui_story_5079_50790500_107_dialog_content = "...",
  ui_story_5079_50790500_108_dialog_content = "Please accept my sincerest apologies. This is not merely tomato soup with carrots in it.",
  ui_story_5079_50790500_109_dialog_content = "In fact, this soup tastes as though it were made entirely of carrots.",
  ui_story_5079_50790500_110_dialog_content = "<color=#e8d9bb>Blegh! Blegh!</color>",
  ui_story_5079_50790500_111_dialog_content = "What is that noise?",
  ui_story_5079_50790500_112_dialog_content = "Sounds like quite a commotion going on outside...",
  ui_story_5079_50790500_113_dialog_content = "...",
  ui_story_5079_50790500_114_dialog_content = "...",
  ui_story_5079_50790500_115_dialog_content = "...",
  ui_story_5079_50790500_116_dialog_content = "Why...",
  ui_story_5079_50790500_117_dialog_content = "<size=50>Why does everything taste like carrots now?</size>",
  ui_story_5079_50790601_1_dialog_content = "Explain the current situation.",
  ui_story_5079_50790601_2_dialog_content = "There is a slight... or rather a severe disturbance in the town...",
  ui_story_5079_50790601_3_dialog_content = "Suddenly, and for reasons still unknown, all of the food in Folta now tastes like carrots—even the rocks and dust were not spared.",
  ui_story_5079_50790601_4_dialog_content = "Do we have any clues regarding this phenomenon?",
  ui_story_5079_50790601_5_dialog_content = "Most of the townspeople are still in a state of panic, making it difficult to glean any meaningful information.",
  ui_story_5079_50790601_6_dialog_content = "However, some rumors have started to emerge. Unfortunately... mentioning them here would be somewhat inconvenient.",
  ui_story_5079_50790601_7_dialog_content = "Never mind that, please share your findings with us.",
  ui_story_5079_50790601_8_dialog_content = "Some believe that this is the work of the carrot shop. After all, that is the only shop that sells carrots here in Folta.",
  ui_story_5079_50790601_9_dialog_content = "To make matters worse, the shop is currently closed for business, and its owner is nowhere to be found.",
  ui_story_5079_50790601_10_dialog_content = "A number of residents found it too strange to be coincidental, so they formed a search party and tried to seek the shop owner and his family out for the truth behind all this.",
  ui_story_5079_50790601_11_dialog_content = "Then it seems we must locate Popo's father before they do... Tell me, have we discovered anything pertaining to his whereabouts?",
  ui_story_5079_50790601_12_dialog_content = "Not yet, milady. I have already tried contacting the conductor.",
  ui_story_5079_50790601_13_dialog_content = "Forgive me... But he still refuses to receive any of your messages.",
  ui_story_5079_50790601_14_dialog_content = "It's been nearly a century, and he's still ignoring me?",
  ui_story_5079_50790601_15_dialog_content = "He's as vexing as ever, I see.",
  ui_story_5079_50790601_16_dialog_content = "Then our only possible leads right now...",
  ui_story_5079_50790601_17_dialog_content = "Huh? I have no idea what's going on, but I swear I didn't do anything!",
  ui_story_5079_50790601_18_dialog_content = "You saw it just now, ma'am. Even a single bite of a carrot is too much for me!",
  ui_story_5079_50790601_19_dialog_content = "So why would I go out of my way to make everything in town taste like them?",
  ui_story_5079_50790601_20_dialog_content = "I can attest to her story. Popo was with me all this time and didn't have the time to pull off something like that.",
  ui_story_5079_50790601_21_dialog_content = "Rest assured, Popo, I have no doubts about you.",
  ui_story_5079_50790601_22_dialog_content = "Your father, on the other hand... Forgive me, but—",
  ui_story_5079_50790601_23_dialog_content = "My father is a perfectly honest merchant!",
  ui_story_5079_50790601_24_dialog_content = "Besides, he's out looking for me right now because he thinks I ran away from home. He would never do something this awful!",
  ui_story_5079_50790601_25_dialog_content = "But...",
  ui_story_5079_50790601_26_dialog_content = "There's no need to say more. I am fully aware of her father's situation.",
  ui_story_5079_50790601_27_dialog_content = "To doubt him is to doubt the veracity of my own information. Do you have any other clues?",
  ui_story_5079_50790601_28_dialog_content = "If he is as innocent as you believe him to be, then there is only one other possibility...",
  ui_story_5079_50790601_29_dialog_content = "Our reports indicate that only a single outsider is visiting Folta today and that her arrival largely coincides with the strange occurrences in our town.",
  ui_story_5079_50790601_30_dialog_content = "Some residents strongly believe that this outsider has the answers they seek.",
  ui_story_5079_50790601_31_dialog_content = "...",
  ui_story_5079_50790601_32_dialog_content = "...",
  ui_story_5079_50790601_33_dialog_content = "Wait, why are you looking at me like that?",
  ui_story_5079_50790601_34_dialog_content = "That thing behind you appears to contain great power.",
  ui_story_5079_50790601_35_dialog_content = "Please forgive me... May I take a closer look at it so that I may clear you of suspicion?",
  ui_story_5079_50790601_36_dialog_content = "!",
  ui_story_5079_50790601_37_dialog_content = "Don't you dare go anywhere near my Hunting Stone.",
  ui_story_5079_50790601_38_dialog_content = "I told you already, I came to Folta to buy ingredients for a banquet. How would making everything taste like carrots benefit me at all?",
  ui_story_5079_50790601_39_dialog_content = "You must excuse my rudeness... But the truth will only be revealed through careful examination.",
  ui_story_5079_50790601_40_dialog_content = "Humph, is this what the Ketchup Family calls \"hospitality\"?",
  ui_story_5079_50790601_41_dialog_content = "If so, let me warn you: I'm not someone you want to upset either!",
  ui_story_5079_50790700_1_dialog_content = "Things got a little out of hand just now. But accusing me without evidence and even attacking me? I couldn't take it anymore.",
  ui_story_5079_50790700_2_dialog_content = "That guy didn't hurt you, did he? Hunting Stone?",
  ui_story_5079_50790700_3_dialog_content = "...",
  ui_story_5079_50790700_4_dialog_content = "<color=#e8d9bb>*footsteps*</color>",
  ui_story_5079_50790700_5_dialog_content = "They caught up quickly, didn't they? Get ready, Hunting Stone!",
  ui_story_5079_50790700_6_dialog_content = "Ahh!",
  ui_story_5079_50790700_7_dialog_content = "Oh, it's just Popo. You can relax now, Hunting Stone.",
  ui_story_5079_50790700_8_dialog_content = "...",
  ui_story_5079_50790700_9_dialog_content = "What... What have you done?",
  ui_story_5079_50790700_10_dialog_content = "I didn't mean to leave you behind, but those people were—",
  ui_story_5079_50790700_11_dialog_content = "You were so cool just now!",
  ui_story_5079_50790700_12_dialog_content = "Ha?",
  ui_story_5079_50790700_13_dialog_content = "You took on the entire Ketchup Family all by yourself! I couldn't even dream of doing something like that!",
  ui_story_5079_50790700_14_dialog_content = "Especially that advisor! I've always been terrified of that guy!",
  ui_story_5079_50790700_15_dialog_content = "Oh, you mean that weirdly polite guy who always apologizes?",
  ui_story_5079_50790700_16_dialog_content = "He wasn't so polite when he threatened us earlier... But I didn't think we'd actually come to blows later.",
  ui_story_5079_50790700_17_dialog_content = "Still, it felt nice to put that apologetic weirdo in his place. I feel I did something similar before...",
  ui_story_5079_50790700_18_dialog_content = "What's going on with me today? It's like everywhere I turn, I keep feeling deja vu...",
  ui_story_5079_50790700_19_dialog_content = "Can I ask you something? Why didn't you just try to explain yourself to them?",
  ui_story_5079_50790700_20_dialog_content = "We're clearly not at fault here, and even the Ketchup Family has to listen to reason! Why pick a meaningless fight with them instead?",
  ui_story_5079_50790700_21_dialog_content = "You said it's meaningless, do you honestly think explaining things would have made a difference?",
  ui_story_5079_50790700_22_dialog_content = "I've tried doing that ever since I was a kid... but no one ever listens. That's why I don't bother anymore.",
  ui_story_5079_50790700_23_dialog_content = "B-But... I overheard someone say that the Ketchup Family has already put out an order for your arrest!",
  ui_story_5079_50790700_24_dialog_content = "Arrest?",
  ui_story_5079_50790700_25_dialog_content = "Even though you looked totally cool while you were fighting the Ketchup Family... The more of a fight you put up, the more they're going to suspect you.",
  ui_story_5079_50790700_26_dialog_content = "How about this? Why don't you tell them that Hunting Stone only attacked because it wanted to protect you, and that you didn't actually want to fight?",
  ui_story_5079_50790700_27_dialog_content = "...",
  ui_story_5079_50790700_28_dialog_content = "It's true that Hunting Stone has a will of its own, and that my power comes from it...",
  ui_story_5079_50790700_29_dialog_content = "But everything just happened was my fault. I'm not about to pin the blame on anyone or anything else.",
  ui_story_5079_50790700_30_dialog_content = "!",
  ui_story_5079_50790700_31_dialog_content = "Oh... I see. You must be really good friends with Hunting Stone. I'm a little jealous, honestly.",
  ui_story_5079_50790700_32_dialog_content = "... Friends? You couldn't be any more wrong.",
  ui_story_5079_50790700_33_dialog_content = "It may be somewhat helpful in a fight, but in everyday life, it brings me nothing but unnecessary trouble.",
  ui_story_5079_50790700_34_dialog_content = "Who would want this freaky thing following them around all the time, or call it a \"friend\" for that matter?",
  ui_story_5079_50790700_35_dialog_content = "Wow... That sounds like the most loyal friend to me! Someone who's always by your side and never leaves you!",
  ui_story_5079_50790700_36_dialog_content = "Okay, now I'm extremely jealous!",
  ui_story_5079_50790700_37_dialog_content = "Don't you ever listen to what people are telling you?",
  ui_story_5079_50790700_38_dialog_content = "It even understands you too! Whenever you're ready to fight, it springs into action!",
  ui_story_5079_50790700_39_dialog_content = "If you don't want it, why don't you let me have it instead?",
  ui_story_5079_50790700_40_dialog_content = "Uh... Or maybe not? I wouldn't want to ruin your guys' friendship, after all!",
  ui_story_5079_50790700_41_dialog_content = "If you can't give it to me, then could I borrow it sometime? Please? Please?",
  ui_story_5079_50790700_42_dialog_content = "...",
  ui_story_5079_50790700_43_dialog_content = "...",
  ui_story_5079_50790700_44_dialog_content = "You saw it in battle just now... Aren't you afraid that it might hurt you?",
  ui_story_5079_50790700_45_dialog_content = "Huh?",
  ui_story_5079_50790700_46_dialog_content = "Besides, we've only known each other for less than a day. Why are you so willing to trust me?",
  ui_story_5079_50790700_47_dialog_content = "Has it ever occurred to you that I'm avoiding the Ketchup Family's investigation because I'm actually guilty?",
  ui_story_5079_50790700_48_dialog_content = "Well... I guess it's because we've been together this whole time.",
  ui_story_5079_50790700_49_dialog_content = "I'm sure you're a good person! My sixth sense tells me so!",
  ui_story_5079_50790700_50_dialog_content = "That's not all, is it? Sorry, Popo, but you're not exactly the best at hiding your thoughts and feelings.",
  ui_story_5079_50790700_51_dialog_content = "For you to trust me so unconditionally, it means you already have another suspect in mind, don't you?",
  ui_story_5079_50790700_52_dialog_content = "That's... That's only part of the reason, but yes!",
  ui_story_5079_50790700_53_dialog_content = "The truth is... I think my father might be responsible for all of this.",
  ui_story_5079_50790700_54_dialog_content = "Carrots were the reason we got into such a huge fight. Maybe he's trying to get me to like carrots by making everything in town taste like them?",
  ui_story_5079_50790700_55_dialog_content = "But would he really go this far just to make me eat carrots? If so, he's going way too far with it!",
  ui_story_5079_50790700_56_dialog_content = "Drop the act. I can tell from your expression that you're not actually angry at him.",
  ui_story_5079_50790700_57_dialog_content = "You don't hate your father at all. You're worried about him—you're worried that he's become the target of the public's anger.",
  ui_story_5079_50790700_58_dialog_content = "What are you talking about? I don't care about any of that. I just feel like I'm partly to blame for our fight.",
  ui_story_5079_50790700_59_dialog_content = "Because of my temper, I always get under my father's skin and make him angry...",
  ui_story_5079_50790700_60_dialog_content = "That's why I feel like I should do something for him... Obviously, that doesn't mean I'm gonna apologize to him or anything!",
  ui_story_5079_50790700_61_dialog_content = "A word of advice: being overly stubborn will only complicate things.",
  ui_story_5079_50790700_62_dialog_content = "Huh? But you're pretty stubborn too, aren't you?",
  ui_story_5079_50790700_63_dialog_content = "Now that I think about it, maybe you and your father had a similar misunderstanding?",
  ui_story_5079_50790700_64_dialog_content = "You could learn a thing or two from me, you know! Like secretly doing something nice for him...",
  ui_story_5079_50790700_65_dialog_content = "I bet he'd really like that.",
  ui_story_5079_50790700_66_dialog_content = "Something that he really likes, huh? Humph, I don't think I can accomplish something like that in my lifetime.",
  ui_story_5079_50790700_67_dialog_content = "Eating carrots, getting rid of Hunting Stone, or becoming the graceful daughter he's always wanted... Urgh, let's just stop bringing up my own matters.",
  ui_story_5079_50790700_68_dialog_content = "Right now, I can more or less guarantee... that your father isn't behind this mess.",
  ui_story_5079_50790700_69_dialog_content = "Huh? Really? So my hunch is completely wrong? Wait, you're not just trying to change the subject, are you?",
  ui_story_5079_50790700_70_dialog_content = "My past isn't really important anymore, but your family is something very near and dear to you.",
  ui_story_5079_50790700_71_dialog_content = "So just forget about my problems for now. As for your father, I'm pretty sure I've figured it all out—",
  ui_story_5079_50790700_72_dialog_content = "If everything tastes like carrots now, it only hurts the interests of the town's only carrot merchant. Get the picture yet?",
  ui_story_5079_50790700_73_dialog_content = "I... I think so! Hmm... If that's the case...",
  ui_story_5079_50790700_74_dialog_content = "Then carrots are completely worthless now, since people can eat whatever they want and still taste them!",
  ui_story_5079_50790700_75_dialog_content = "Bingo. It wouldn't make sense for your father to do something so harmful to his business.",
  ui_story_5079_50790700_76_dialog_content = "Ohhh! That... That makes total sense! You're not also a detective, are you?",
  ui_story_5079_50790700_77_dialog_content = "It's just simple observation, that's all. You're pretty good at analyzing the facts too, Popo. Something tells me...",
  ui_story_5079_50790700_78_dialog_content = "We might be able to work together pretty well.",
  ui_story_5079_50790700_79_dialog_content = "Heeheehee, I figured that out a long time ago!",
  ui_story_5079_50790700_80_dialog_content = "(Is that why I've been so willing to stick around? Because our way of thinking is so similar?)",
  ui_story_5079_50790700_81_dialog_content = "(Our stubborn personalities and relationships with our fathers are also pretty similar...)",
  ui_story_5079_50790700_82_dialog_content = "(Could it be that she's an exact copy of me from when I was a kid? No, that can't be right... I'm positive I was a bit more mature than her.)",
  ui_story_5079_50790700_83_dialog_content = "Then... Could you help me out with something else?",
  ui_story_5079_50790700_84_dialog_content = "Of course! After all, that's what a mature person would... ahem, I mean yes, what is it?",
  ui_story_5079_50790700_85_dialog_content = "I... I think I can smell the source of the carrot flavoring! As if it's connected to me somehow!",
  ui_story_5079_50790700_86_dialog_content = "Or maybe it's because I hate carrots so much that I'm more sensitive to them than other people.",
  ui_story_5079_50790700_87_dialog_content = "The smell... It seems to come from <color=#FFB400>Cream Forest</color>. It's far from here, and there's a cave dedicated to the Food God there.",
  ui_story_5079_50790700_88_dialog_content = "You can smell something coming from a forest cave miles from here?",
  ui_story_5079_50790700_89_dialog_content = "Nope! But my father used to take me to play in that cave all the time. If I have to guess, he must have taken the train to go look for me in that cave!",
  ui_story_5079_50790700_90_dialog_content = "If that's where he is right now, and something creepy is actually happening in the forest...",
  ui_story_5079_50790700_91_dialog_content = "You don't have to keep trying to hide it. It's clear that you're really worried about your father.",
  ui_story_5079_50790700_92_dialog_content = "Alright fine, I am worried! And that's why... I'd like to borrow your Hunting Stone and go rescue him!",
  ui_story_5079_50790700_93_dialog_content = "You think you'll be fine on your own?",
  ui_story_5079_50790700_94_dialog_content = "Uh...",
  ui_story_5079_50790700_95_dialog_content = "Admit it, you're waiting for me to offer my help.",
  ui_story_5079_50790700_96_dialog_content = "You're the only one I can count on right now... But helping me works out for you too!",
  ui_story_5079_50790700_97_dialog_content = "Oh? How so?",
  ui_story_5079_50790700_98_dialog_content = "Helping me find my father wouldn't be a problem for you at all, and once we do, I'm sure he'll do everything he can to clear your good name.",
  ui_story_5079_50790700_99_dialog_content = "And if you manage to get rid of the carrot taste for the town, gathering your ingredients will only be that much easier, right?",
  ui_story_5079_50790700_100_dialog_content = "I knew it...",
  ui_story_5079_50790700_101_dialog_content = "Huh? Knew what?",
  ui_story_5079_50790700_102_dialog_content = "Nothing. You just impress me sometimes, that's all.",
  ui_story_5079_50790700_103_dialog_content = "I'll help you out, but not because you persuaded me or anything. Our thoughts just happen to line up.",
  ui_story_5079_50790700_104_dialog_content = "Really? Really? Then maybe I have some detective potential in me too!",
  ui_story_5079_50790700_105_dialog_content = "It's definitely a talent worth training. Maybe I'll introduce you to some of my favorite rules someday.",
  ui_story_5079_50790700_106_dialog_content = "Rules?",
  ui_story_5079_50790700_107_dialog_content = "Interested? I'll let you know all about them when we have some spare time, but right now...",
  ui_story_5079_50790700_108_dialog_content = "Let's head to the forest!",
  ui_story_5079_50790700_109_dialog_content = "Alright! Let's go!",
  ui_story_5079_50790801_1_dialog_content = "Urgh... The smell out here is horrific. It definitely comes from one place...",
  ui_story_5079_50790801_2_dialog_content = "Could it be the cave of the Food God?",
  ui_story_5079_50790801_3_dialog_content = "Speaking of which, do you think this god is involved somehow?",
  ui_story_5079_50790801_4_dialog_content = "I'd rather not talk about it. After all, the Food God is Folta's most revered deity.",
  ui_story_5079_50790801_5_dialog_content = "We make regular offerings, and in exchange, the Food God grants our most sincere wishes.",
  ui_story_5079_50790801_6_dialog_content = "Is that why you suspected your father earlier? Because you think he might've gone to the Food God and wished for everything to taste like carrots?",
  ui_story_5079_50790801_7_dialog_content = "Yeah...",
  ui_story_5079_50790801_8_dialog_content = "Can this Food God really make a wish like that come true?",
  ui_story_5079_50790801_9_dialog_content = "Of course! The Ketchup Family received their sacred Black Cookbook from the Food God.",
  ui_story_5079_50790801_10_dialog_content = "That family's been in power for generations all thanks to the knowledge found in that book.",
  ui_story_5079_50790801_11_dialog_content = "Something suddenly feels wrong...",
  ui_story_5079_50790801_12_dialog_content = "Don't tell me there's someone who holds a white suitcase packed with ingredients staying close to the head of the Ketchup Family.",
  ui_story_5079_50790801_13_dialog_content = "I... I think so? Wait, does this mean you've looked into the Ketchup Family already?",
  ui_story_5079_50790801_14_dialog_content = "Not at all, but something about the entire Ketchup Family makes me feel... nostalgic?",
  ui_story_5079_50790801_15_dialog_content = "That's not important right now... What's important is finding a way to get to that forest.",
  ui_story_5079_50790801_16_dialog_content = "The fastest way to Cream Forest is by train, but...",
  ui_story_5079_50790801_17_dialog_content = "No sign of them here either? You men, search that area.",
  ui_story_5079_50790801_18_dialog_content = "Yes, sir!",
  ui_story_5079_50790801_19_dialog_content = "The street is full of people who are looking for you right now...",
  ui_story_5079_50790801_20_dialog_content = "Urgh, what a pain. If my mission weren't so important, I'd go mop the floor with that weirdo one more time.",
  ui_story_5079_50790801_21_dialog_content = "Listen up, Popo. If they find me and I can't avoid a fight, you need to take Hunting Stone and go straight to the forest.",
  ui_story_5079_50790801_22_dialog_content = "No way, I could never leave you behind! We're the perfect partners now, remember?",
  ui_story_5079_50790801_23_dialog_content = "I even picked out a name for us! \"The Anti-Carrot Dream Team\"!",
  ui_story_5079_50790801_24_dialog_content = "Is that really the best you could come up with? Can't you at least try to—",
  ui_story_5079_50790801_25_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_5079_50790801_26_dialog_content = "Look out, Popo!",
  ui_story_5079_50790801_27_dialog_content = "Huh?",
  ui_story_5079_50790801_28_dialog_content = "!",
  ui_story_5079_50790801_29_dialog_content = "Phew... That was a close call.",
  ui_story_5079_50790801_30_dialog_content = "Now then... Can someone tell me why a bunch of fruits and vegetables are flying through the air?",
  ui_story_5079_50790801_31_dialog_content = "Stay behind Hunting Stone, Popo. Don't get too close.",
  ui_story_5079_50790801_32_dialog_content = "O-Okay... But what's going on over here?",
  ui_story_5079_50790801_33_dialog_content = "...",
  ui_story_5079_50790801_34_dialog_content = "Stop! What do you think you're doing? Are you gophers or something? Why are you trying to ruin the delicious taste of carrots?",
  ui_story_5079_50790801_35_dialog_content = "We just want everything to taste the way it's supposed to taste!",
  ui_story_5079_50790801_36_dialog_content = "Quick, sprinkle some more salt and baking soda on everything! The more the better!",
  ui_story_5079_50790801_37_dialog_content = "Stop! This has to be nature's next step in evolution. We won't let you interfere with the Food God's will!",
  ui_story_5079_50790801_38_dialog_content = "Besides, you all like carrots, don't you? Why stand against us?",
  ui_story_5079_50790801_39_dialog_content = "I... I like carrots and all, but I don't want to spend the rest of my life eating them!",
  ui_story_5079_50790801_40_dialog_content = "I'm sorry!",
  ui_story_5079_50790801_41_dialog_content = "Stop! Stop it right now!",
  ui_story_5079_50790801_42_dialog_content = "For a perfect and carrot-filled world! Charge!",
  ui_story_5079_50790801_43_dialog_content = "For Folta and its proud culinary diversity! Sprinkle!",
  ui_story_5079_50790801_44_dialog_content = "Wow... The whole town has gone bonkers, hasn't it?",
  ui_story_5079_50790801_45_dialog_content = "So many buildings have already been destroyed. At this rate, Folta won't be the same town anymore...",
  ui_story_5079_50790801_46_dialog_content = "And my mission will be as good as failed. Urgh, what a pain...",
  ui_story_5079_50790801_47_dialog_content = "Nothing bothers me more than this kind of chaos and disorder.",
  ui_story_5079_50790801_48_dialog_content = "...",
  ui_story_5079_50790801_49_dialog_content = "Look! Hunting Stone's moving!",
  ui_story_5079_50790801_50_dialog_content = "Hey! Don't cause more problems for us by jumping into the fight!",
  ui_story_5079_50790801_51_dialog_content = "No wait, it looks like Hunting Stone is trying to lead us this way.",
  ui_story_5079_50790801_52_dialog_content = "... Is that so?",
  ui_story_5079_50790801_53_dialog_content = "Hey, don't think I'm gonna follow you around just because you want me to.",
  ui_story_5079_50790801_54_dialog_content = "...",
  ui_story_5079_50790801_55_dialog_content = "And now you don't want me to catch up? Don't think you can outrun me, you rotten wheel!",
  ui_story_5079_50790801_56_dialog_content = "Let's go, Popo.",
  ui_story_5079_50790801_57_dialog_content = "<size=30>Why is she getting so worked up? I guess she is pretty immature after all...</size>",
  ui_story_5079_50790801_58_dialog_content = "What was that?",
  ui_story_5079_50790801_59_dialog_content = "Nothing! I'm coming!",
  ui_story_5079_50790801_60_dialog_content = "You want us to cut through here? Well, it's the train station.",
  ui_story_5079_50790801_61_dialog_content = "Well done, Hunting Stone.",
  ui_story_5079_50790801_62_dialog_content = "!",
  ui_story_5079_50790801_63_dialog_content = "But don't get too full of yourself. If you end up scaring anyone on the train again...",
  ui_story_5079_50790801_64_dialog_content = "I'm taking back my compliment.",
  ui_story_5079_50790801_65_dialog_content = "Hurry up, would you? I don't want to miss the train twice in one day!",
  ui_story_5079_50790801_66_dialog_content = "Hey, be careful...",
  ui_story_5079_50790801_67_dialog_content = "<color=#e8d9bb>Wham!</color>",
  ui_story_5079_50790801_68_dialog_content = "Well, at least she managed to run into someone twice today...",
  ui_story_5079_50790801_69_dialog_content = "Ouch...",
  ui_story_5079_50790801_70_dialog_content = "Huh? Is that you, Popo?",
  ui_story_5079_50790801_71_dialog_content = "Uh-oh!",
  ui_story_5079_50790801_72_dialog_content = "Everyone in Folta has lost their mind over this carrot business.",
  ui_story_5079_50790801_73_dialog_content = "As the daughter of the only carrot merchant in town, you should be more careful out here.",
  ui_story_5079_50790801_74_dialog_content = "Uh... Okay, but...",
  ui_story_5079_50790801_75_dialog_content = "Here, I'll escort you back.",
  ui_story_5079_50790801_76_dialog_content = "B-But I have to catch the train.",
  ui_story_5079_50790801_77_dialog_content = "The train? You mean the one going to Cream Forest? Wait a minute...",
  ui_story_5079_50790801_78_dialog_content = "Who's that person next to you? Hang on, that wheel... I've heard about it before! Could she be...",
  ui_story_5079_50790801_79_dialog_content = "Spare us the theatrics already. Yes, it's me—the evil intruder from out of town. Happy now?",
  ui_story_5079_50790801_80_dialog_content = "Go ahead and board the train, Popo. I'll take things from here.",
  ui_story_5079_50790901_1_dialog_content = "W-Wait, stop! Both of you!",
  ui_story_5079_50790901_2_dialog_content = "...",
  ui_story_5079_50790901_3_dialog_content = "...",
  ui_story_5079_50790901_4_dialog_content = "I know you! You're one of our shop's regulars, aren't you?",
  ui_story_5079_50790901_5_dialog_content = "You love carrots, which is why you're fighting to keep things the way they are right now! Right? Right?",
  ui_story_5079_50790901_6_dialog_content = "Yes... I knew the daughter of our great carrot merchant would understand.",
  ui_story_5079_50790901_7_dialog_content = "Then there's no reason for us to fight! You know why the Ketchup Family is after my friend here, right?",
  ui_story_5079_50790901_8_dialog_content = "... Does this mean the rumors are true?",
  ui_story_5079_50790901_9_dialog_content = "Not exactly, no. She's a detective, and she's helping me look for my father right now.",
  ui_story_5079_50790901_10_dialog_content = "Ahem... Pactlock Holmes, at your service.",
  ui_story_5079_50790901_11_dialog_content = "I see, I see. Whether you're an actual detective or not, we owe you our gratitude!",
  ui_story_5079_50790901_12_dialog_content = "In fact, we'll be honored if you serve as our organization's Carrot Saintess!",
  ui_story_5079_50790901_13_dialog_content = "No thanks, but if you really want to express your gratitude...",
  ui_story_5079_50790901_14_dialog_content = "I need to get on that train, but I'm not sure what the station is like right now. Think you can give me some cover?",
  ui_story_5079_50790901_15_dialog_content = "Of course! If I'm not mistaken, the person selling train tickets belongs to the enemy's faction.",
  ui_story_5079_50790901_16_dialog_content = "I'll make sure none of them manage to see you!",
  ui_story_5079_50790901_17_dialog_content = "There, now's your chance! My people got his attention, and a fight should be breaking out soon...",
  ui_story_5079_50790901_18_dialog_content = "Head into the station as fast as you can!",
  ui_story_5079_50790901_19_dialog_content = "Thanks... But why are you and your people willing to go this far just for the sake of carrots?",
  ui_story_5079_50790901_20_dialog_content = "Naturally, it's because we can't even begin to describe our love for carrots!",
  ui_story_5079_50790901_21_dialog_content = "Crispy and sweet, they have such a wonderful texture. You could eat a hundred carrots without getting sick of them!",
  ui_story_5079_50790901_22_dialog_content = "They're also an excellent source of energy and nutrition! They can promote bone growth and development, improve complexion, and even relieve eye fatigue!",
  ui_story_5079_50790901_23_dialog_content = "But most importantly, these magnificent vegetables can treat constipation! Those carrot-haters must be so conflicted about that right now!",
  ui_story_5079_50790901_24_dialog_content = "... I-Is that so?",
  ui_story_5079_50790901_25_dialog_content = "<size=30>I had no idea carrots had so many good qualities.</size>",
  ui_story_5079_50790901_26_dialog_content = "But why do you ask, Carrot Saintess? Unless... Ah, I see!",
  ui_story_5079_50790901_27_dialog_content = "You were testing my devotion to the almighty carrot just now, weren't you? Rest assured, my saintess, I will always be on the side of carroty goodness!",
  ui_story_5079_50790901_28_dialog_content = "Uh... Okay then. I respect your decision.",
  ui_story_5079_50790901_29_dialog_content = "We should get going, Popo.",
  ui_story_5079_50790901_30_dialog_content = "Just a moment. You're going with her too, Popo?",
  ui_story_5079_50790901_31_dialog_content = "Yeah, of course. Is that a problem?",
  ui_story_5079_50790901_32_dialog_content = "Our enemies may have eyes outside of the town. They may not recognize the Carrot Saintess, but they'll definitely recognize you.",
  ui_story_5079_50790901_33_dialog_content = "It would be dangerous for you to go along!",
  ui_story_5079_50790901_34_dialog_content = "That's true... It might be better for you to stay here, Popo. I'm sure your shop's regulars will take good care of you.",
  ui_story_5079_50790901_35_dialog_content = "But... But I wanna help you—",
  ui_story_5079_50790901_36_dialog_content = "Rest assured, my people and I will do everything in our power to protect Princess Popo.",
  ui_story_5079_50790901_37_dialog_content = "P-Princess?",
  ui_story_5079_50790901_38_dialog_content = "You'll be fine, Popo. Remember how you wanted to borrow Hunting Stone earlier?",
  ui_story_5079_50790901_39_dialog_content = "Since it likes you so much, I'm sure it won't mind staying by your side. That way you'll have nothing to worry about, right?",
  ui_story_5079_50790901_40_dialog_content = "But then... Won't that make things more dangerous for you?",
  ui_story_5079_50790901_41_dialog_content = "Me? Are you kidding? I'd feel a lot better without Hunting Stone following me around.",
  ui_story_5079_50790901_42_dialog_content = "Besides, you're friends with it now, right? You can even understand its feelings.",
  ui_story_5079_50790901_43_dialog_content = "And it really seems to want to stay with you...",
  ui_story_5079_50790901_44_dialog_content = "?",
  ui_story_5079_50790901_45_dialog_content = "If it were anyone else, it would roll right back to me right away.",
  ui_story_5079_50790901_46_dialog_content = "Does that mean... I'm special?",
  ui_story_5079_50790901_47_dialog_content = "Looks like it. So just stay here and wait for me, okay?",
  ui_story_5079_50790901_48_dialog_content = "O-Okay... I'll do exactly as you asked! Isn't that right, Hunting Stone?",
  ui_story_5079_50790901_49_dialog_content = "!",
  ui_story_5079_50790901_50_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790901_51_dialog_content = "Your attention please, everybody! It is my honor to introduce you all to Princess Popo, daughter of our town's venerable carrot merchant!",
  ui_story_5079_50790901_52_dialog_content = "Welcome!",
  ui_story_5079_50790901_53_dialog_content = "H-Hello, everyone.",
  ui_story_5079_50790901_54_dialog_content = "To make you feel more at home, I've prepared a very special cake just for you! Please enjoy, Princess Popo!",
  ui_story_5079_50790901_55_dialog_content = "Please enjoy!",
  ui_story_5079_50790901_56_dialog_content = "I spent my blood, sweat, and tears baking this cake for you! I even added mashed carrots to the cream...",
  ui_story_5079_50790901_57_dialog_content = "Naturally, I only used the freshest and highest-quality carrots from your father's shop!",
  ui_story_5079_50790901_58_dialog_content = "Although it seems somewhat redundant to bake a carrot cake for the daughter of a carrot merchant, I hope you enjoy it all the same.",
  ui_story_5079_50790901_59_dialog_content = "We hope so too!",
  ui_story_5079_50790901_60_dialog_content = "Well...",
  ui_story_5079_50790901_61_dialog_content = "Please enjoy, princess.",
  ui_story_5079_50790901_62_dialog_content = "C-Can I eat it in a nice, quiet place? I'm not used to eating in front of this many people...",
  ui_story_5079_50790901_63_dialog_content = "Of course, princess! But if I may ask, why do you look so queasy?",
  ui_story_5079_50790901_64_dialog_content = "Could it be that my carrot cake is not up to your standards?",
  ui_story_5079_50790901_65_dialog_content = "No, that's not it...",
  ui_story_5079_50790901_66_dialog_content = "Now that I think about it, has anyone actually seen the carrot merchant's daughter eat a carrot before?",
  ui_story_5079_50790901_67_dialog_content = "No, but I saw her argue with her father once, and it sounded like carrots were the reason behind their fight...",
  ui_story_5079_50790901_68_dialog_content = "?",
  ui_story_5079_50790901_69_dialog_content = "I... I love carrots! You just haven't seen me eat them, that's all... S-See? Th-They're delicious...",
  ui_story_5079_50790901_70_dialog_content = "Urgh... Blegh...",
  ui_story_5079_50790901_71_dialog_content = "Are you seriously pinching your nose right now?",
  ui_story_5079_50790901_72_dialog_content = "Y-You don't understand! This is the best way to experience the taste of carrots—",
  ui_story_5079_50790901_73_dialog_content = "<size=45>Pffffft—</size>",
  ui_story_5079_50790901_74_dialog_content = "...",
  ui_story_5079_50790901_75_dialog_content = "...",
  ui_story_5079_50790901_76_dialog_content = "...",
  ui_story_5079_50790901_77_dialog_content = "You don't like carrots at all, do you? You're not our princess, but our sworn enemy!",
  ui_story_5079_50790901_78_dialog_content = "Your friend went to Cream Forest to search for your father, right?",
  ui_story_5079_50790901_79_dialog_content = "What could she be doing out there? Could it be that she's trying to destroy our beautiful, carrot-filled paradise?",
  ui_story_5079_50790901_80_dialog_content = "Quickly! We have to capture Popo and force her to lead us to that woman!",
  ui_story_5079_50790901_81_dialog_content = "No... D-Don't come any closer!",
  ui_story_5079_50790901_82_dialog_content = "You'll help me, won't you? Hunting Stone?",
  ui_story_5079_50790901_83_dialog_content = "!",
  ui_story_5079_50791001_1_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50791001_2_dialog_content = "A pleasure to meet you again, milady. We have arrived in Cream Forest, please watch your step as you step off the train.",
  ui_story_5079_50791001_3_dialog_content = "Oh... We're already here? That was a lot faster than I expected...",
  ui_story_5079_50791001_4_dialog_content = "Things are almost strangely boring without an annoying kid or a clingy sidekick tagging along.",
  ui_story_5079_50791001_5_dialog_content = "It was actually quite a lengthy journey, though you spent most of that time staring out the window.",
  ui_story_5079_50791001_6_dialog_content = "Is the unrest in Folta the source of your stress? Can I be of any assistance?",
  ui_story_5079_50791001_7_dialog_content = "So you're aware of what's going on in the town?",
  ui_story_5079_50791001_8_dialog_content = "Never mind that, I have something more important to ask. Have you seen the owner of the carrot shop lately?",
  ui_story_5079_50791001_9_dialog_content = "From what I've heard, he left town on this train earlier today.",
  ui_story_5079_50791001_10_dialog_content = "The carrot merchant? Why yes, actually. He got off at this very station, and I believe he mentioned going to the Food God's cave.",
  ui_story_5079_50791001_11_dialog_content = "Really? Looks like Popo was right all along.",
  ui_story_5079_50791001_12_dialog_content = "I believe you have an impression of him as well.",
  ui_story_5079_50791001_13_dialog_content = "After all, you met him when you first arrived in Folta. It was quite an amusing encounter, I must say.",
  ui_story_5079_50791001_14_dialog_content = "I met him? You mean that extremely modest passenger was Popo's father?",
  ui_story_5079_50791001_15_dialog_content = "Urgh, this entire mess could've been avoided if I had just stopped him from boarding the train back then...",
  ui_story_5079_50791001_16_dialog_content = "It appears your question has been answered. Please remember to take your luggage as you get off the train... Er, just a moment.",
  ui_story_5079_50791001_17_dialog_content = "Pardon me, but did you finally do away with Hunting Stone?",
  ui_story_5079_50791001_18_dialog_content = "Surely you didn't abandon it in a dark corner of town and leave it to suffer in wretched solitude, did you?",
  ui_story_5079_50791001_19_dialog_content = "You don't have to make it sound so miserable...",
  ui_story_5079_50791001_20_dialog_content = "I just left it with someone else for the time being.",
  ui_story_5079_50791001_21_dialog_content = "Forgive me, I couldn't help but imagine a scene of immense tragedy and loneliness just now.",
  ui_story_5079_50791001_22_dialog_content = "I believe its rightful place is at your side, and the same goes for you as well.",
  ui_story_5079_50791001_23_dialog_content = "I really don't need your thoughts on our relationship... But thanks for the info.",
  ui_story_5079_50791001_24_dialog_content = "Think nothing of it. I'm delighted to assist you.",
  ui_story_5079_50791001_25_dialog_content = "Speaking of which, the head of the Ketchup Family tried to contact you about Popo's father too.",
  ui_story_5079_50791001_26_dialog_content = "But you refused to answer her... I thought you were a heartless person at first, but it turns out you're actually pretty warm-hearted.",
  ui_story_5079_50791001_27_dialog_content = "If the request were from you, my dear passenger, I would have gone to any lengths to help you.",
  ui_story_5079_50791001_28_dialog_content = "But I refuse to deal with that mad woman in any capacity. I would rather spend all eternity in cold solitude than reconnect with her!",
  ui_story_5079_50791001_29_dialog_content = "I-I understand, sorry if I upset you. I'll get off the train right away.",
  ui_story_5079_50791001_30_dialog_content = "The smell of carrots is getting stronger and stronger...",
  ui_story_5079_50791001_31_dialog_content = "The source of the problem should be around here somewhere.",
  ui_story_5079_50791001_32_dialog_content = "Graaah!",
  ui_story_5079_50791001_33_dialog_content = "Wh-What?",
  ui_story_5079_50791001_34_dialog_content = "What are Eclipsites doing in a place like this?",
  ui_story_5079_50791001_35_dialog_content = "I knew there was something strange about this carrot stench... Is the Food God's power somehow connected to Eclipsites?",
  ui_story_5079_50791001_36_dialog_content = "If so, Folta is in much more danger than we realized.",
  ui_story_5079_50791001_37_dialog_content = "I need to avoid them for now and check out the cave...",
  ui_story_5079_50791001_38_dialog_content = "Graaah!",
  ui_story_5079_50791001_39_dialog_content = "Tsk, the closer I get to the cave, the more Eclipsites appear.",
  ui_story_5079_50791001_40_dialog_content = "Alright, Hunting Stone, let's...",
  ui_story_5079_50791001_41_dialog_content = "No wait, Hunting Stone isn't with me right now... Can I really handle this many Eclipsites on my own?",
  ui_story_5079_50791001_42_dialog_content = "... Heh.",
  ui_story_5079_50791001_43_dialog_content = "What's the matter, Pact? When did you get this weak?",
  ui_story_5079_50791001_44_dialog_content = "Without Hunting Stone, taking out these Eclipsites should be much easier!",
  ui_story_5079_50791001_45_dialog_content = "Come and get us... I mean, me! Come and get me!",
  ui_story_5079_50791001_46_dialog_content = "<color=#e8d9bb>Whack!</color>",
  ui_story_5079_50791001_47_dialog_content = "...",
  ui_story_5079_50791001_48_dialog_content = "Graaah!",
  ui_story_5079_50791001_49_dialog_content = "... Bind!",
  ui_story_5079_50791001_50_dialog_content = "Graaah!",
  ui_story_5079_50791001_51_dialog_content = "Tsk... My attacks were a lot slower, and they broke out of my bindings much sooner than I expected.",
  ui_story_5079_50791001_52_dialog_content = "I wouldn't have so much trouble against these ridiculously weak Eclipsites if I had Hunting Stone with me...",
  ui_story_5079_50791001_53_dialog_content = "This can't be happening... I'm actually starting to miss that stupid wheel! I'm such a joke...",
  ui_story_5079_50791001_54_dialog_content = "I should rely on my own strength right now...",
  ui_story_5079_50791100_1_dialog_content = "Graah—",
  ui_story_5079_50791100_2_dialog_content = "Phew... That should be the last of them.",
  ui_story_5079_50791100_3_dialog_content = "See? My Luminatics are still strong enough to take down this many Eclipsites <color=#FFB400>on my own</color>.",
  ui_story_5079_50791100_4_dialog_content = "Although in the past, it wouldn't take so much out of me.",
  ui_story_5079_50791100_5_dialog_content = "Hunting Stone... I don't need it to fight, but it does have some uses...",
  ui_story_5079_50791100_6_dialog_content = "Graaah!",
  ui_story_5079_50791100_7_dialog_content = "Ah!",
  ui_story_5079_50791100_8_dialog_content = "I dropped my guard! I have to—",
  ui_story_5079_50791100_9_dialog_content = "!",
  ui_story_5079_50791100_10_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5079_50791100_11_dialog_content = "Hunting Stone? Who told you to come back to me? Don't tell me you—",
  ui_story_5079_50791100_12_dialog_content = "Hey! Are you okay?",
  ui_story_5079_50791100_13_dialog_content = "Popo? Heh, of course I'm okay. Just give me a second to clean up the rest of these Eclipsites.",
  ui_story_5079_50791100_14_dialog_content = "Have a taste of my beautiful thorns!",
  ui_story_5079_50791100_15_dialog_content = "<color=#e8d9bb>Pew! Smack!</color>",
  ui_story_5079_50791100_16_dialog_content = "Graaah!",
  ui_story_5079_50791100_17_dialog_content = "I can help too! Hunting Stone!",
  ui_story_5079_50791100_18_dialog_content = "!",
  ui_story_5079_50791100_19_dialog_content = "Graaah...",
  ui_story_5079_50791100_20_dialog_content = "We did it! We did it! We took out all of those nasty Eclipsites together!",
  ui_story_5079_50791100_21_dialog_content = "That's right we did! You were incredible, Popo. I had no idea you could use Luminatics!",
  ui_story_5079_50791100_22_dialog_content = "That's because I couldn't... at least not before.",
  ui_story_5079_50791100_23_dialog_content = "But I was so scared when I saw those Eclipsites attack you, and suddenly this power welled up inside of me!",
  ui_story_5079_50791100_24_dialog_content = "I honestly can't believe it. I bet my father will be so happy when he finds out!",
  ui_story_5079_50791100_25_dialog_content = "Y-Yeah... Definitely...",
  ui_story_5079_50791100_26_dialog_content = "(The source of Popo's power is the same as my own, and she seems to have a lot of potential...)",
  ui_story_5079_50791100_27_dialog_content = "(Is that why she was able to command Hunting Stone? I thought it was only supposed to obey me...)",
  ui_story_5079_50791100_28_dialog_content = "The smell of carrots comes from the Food God's cave! I'm certain of it now!",
  ui_story_5079_50791100_29_dialog_content = "I hear a voice too... It's telling me to come closer!",
  ui_story_5079_50791100_30_dialog_content = "A voice? I think you're just eager to find your father...",
  ui_story_5079_50791100_31_dialog_content = "Guess that means you care about him a lot more than you let on...",
  ui_story_5079_50791100_32_dialog_content = "Anyway, didn't I tell you to wait for me back in town? What made you come after me?",
  ui_story_5079_50791100_33_dialog_content = "About that... Those carrot-loving crazies forced me to eat their carrot cake, and I ended up spitting it out. That's when I knew my cover was blown.",
  ui_story_5079_50791100_34_dialog_content = "So I took off with Hunting Stone, but I didn't realize it was even faster than a train. We got here in almost no time at all... You're not mad at me, are you?",
  ui_story_5079_50791100_35_dialog_content = "Of course not. If anything, I'm furious those grown-ups tried to punish you with something so disgusting!",
  ui_story_5079_50791100_36_dialog_content = "Right? Right? I couldn't stomach a single bite! That's why I had no choice but to come find you.",
  ui_story_5079_50791100_37_dialog_content = "I knew it all along—the Anti-Carrot Dream Team has to stick together no matter what!",
  ui_story_5079_50791100_38_dialog_content = "<size=30>But there's only one Hunting Stone...</size>",
  ui_story_5079_50791100_39_dialog_content = "Huh?",
  ui_story_5079_50791100_40_dialog_content = "(Popo probably hasn't realized it yet. Her Luminatics are still too weak, so she has to rely on Hunting Stone to use them...)",
  ui_story_5079_50791100_41_dialog_content = "What's the big deal, Hunting Stone? Normally I can never get rid of you, but you seem pretty attached to your new master now...",
  ui_story_5079_50791100_42_dialog_content = "Since you've chosen her over me, you'd better take good care of her. Understand?",
  ui_story_5079_50791100_43_dialog_content = "You don't have to follow me around anymore, so let me finally enjoy some peace and quiet.",
  ui_story_5079_50791100_44_dialog_content = "...",
  ui_story_5079_50791100_45_dialog_content = "What are you whispering about over there?",
  ui_story_5079_50791100_46_dialog_content = "As a member of the team, I demand to know!",
  ui_story_5079_50791100_47_dialog_content = "Don't worry about it. Besides, I have better news to share with you. I spoke to the train conductor, and he said your father got off the train here.",
  ui_story_5079_50791100_48_dialog_content = "He's definitely involved in this crazy incident, though I'm not exactly sure how.",
  ui_story_5079_50791100_49_dialog_content = "Could it be that father really...",
  ui_story_5079_50791100_50_dialog_content = "I'll head into the forest and check things out. You and Hunting Stone can keep watch out here.",
  ui_story_5079_50791100_51_dialog_content = "Not happening! If you're going into the forest, then so am I!",
  ui_story_5079_50791100_52_dialog_content = "There are Eclipsites lurking around here, and there's only gonna be more of them in the forest. Letting you come along would be too dangerous.",
  ui_story_5079_50791100_53_dialog_content = "But I can use Luminatics now! I can help!",
  ui_story_5079_50791100_54_dialog_content = "You just discovered your powers today, didn't you? Using them to protect yourself will take everything you've got, and I won't have time to come to your rescue...",
  ui_story_5079_50791100_55_dialog_content = "I can handle myself just fine. We're supposed to be helping each other out, just like we agreed!",
  ui_story_5079_50791100_56_dialog_content = "Besides, didn't I save you from a bunch of Eclipsites just now?",
  ui_story_5079_50791100_57_dialog_content = "...",
  ui_story_5079_50791100_58_dialog_content = "(All I could think about before was getting rid of Hunting Stone, but after seeing how close it has gotten to Popo, I...)",
  ui_story_5079_50791100_59_dialog_content = "Just say it, you don't trust me at all, do you?",
  ui_story_5079_50791100_60_dialog_content = "It's not that I don't trust you. I'm just worried that your father will be disappointed if he sees your half-baked Luminatics in action.",
  ui_story_5079_50791100_61_dialog_content = "Wh-What? No way... Father has always dreamed that I would learn how to use Luminatics someday!",
  ui_story_5079_50791100_62_dialog_content = "Really? But if you learn Luminatics, his expectations will only go higher and higher. He won't stop until you become his ideal daughter...",
  ui_story_5079_50791100_63_dialog_content = "But who knows when will he be satisfied? In fact, he might even...",
  ui_story_5079_50791100_64_dialog_content = "...",
  ui_story_5079_50791100_65_dialog_content = "Uh, it's nothing. Forget I said anything...",
  ui_story_5079_50791100_66_dialog_content = "I... I'm not that excited to show him my Luminatics...",
  ui_story_5079_50791100_67_dialog_content = "It doesn't matter to me as long as I know he's safe. Helping you with your mission is much more important.",
  ui_story_5079_50791100_68_dialog_content = "Besides, we'll get there faster if I lead the way. Trust me, I know plenty of shortcuts!",
  ui_story_5079_50791100_69_dialog_content = "Shortcuts? <size=30>Hunting Stone, make sure there aren't any Eclipsites in Popo's way.</size>",
  ui_story_5079_50791100_70_dialog_content = "...",
  ui_story_5079_50791100_71_dialog_content = "Tsk, it went off to protect her without any hesitation...",
  ui_story_5079_50791100_72_dialog_content = "Well, at least it's nice and quiet walking alone.",
  ui_story_5079_50791100_73_dialog_content = "As long as it helps me complete my mission... I suppose I can keep up for now.",
  ui_story_5079_50791100_74_dialog_content = "My lady, the base of those carrot fanatics in western Folta is under our control now.",
  ui_story_5079_50791100_75_dialog_content = "Though it took much persuading, the carrot-haters on the east side of town have also agreed to stop rioting.",
  ui_story_5079_50791100_76_dialog_content = "Folta's peace has been restored, albeit temporarily. However...",
  ui_story_5079_50791100_77_dialog_content = "The outsider and Popo have yet to be captured, yes?",
  ui_story_5079_50791100_78_dialog_content = "My own inadequacy is to blame... Please forgive me...",
  ui_story_5079_50791100_79_dialog_content = "No, this has nothing to do with you. These events have long since been foretold by the Black Cookbook...",
  ui_story_5079_50791100_80_dialog_content = "\"Those who detest it shall nurture it. In doing so, they shall also end it.\"",
  ui_story_5079_50791100_81_dialog_content = "Pardon my ignorance, but what exactly does this prophecy—",
  ui_story_5079_50791100_82_dialog_content = "It means that the ones who despise carrots the most are responsible for this disaster, and they are also the ones who will bring an end to it.",
  ui_story_5079_50791100_83_dialog_content = "They're clearly two people, yet they are also one and the same... What an interesting prophecy.",
  ui_story_5079_50791100_84_dialog_content = "They've gone towards the cave of the Food God, haven't they?",
  ui_story_5079_50791100_85_dialog_content = "Yes, my lady. Shall we go after them?",
  ui_story_5079_50791100_86_dialog_content = "Heheh, I'm afraid not. This dream doesn't belong to us, which means we have no right to interfere.",
  ui_story_5079_50791100_87_dialog_content = "Tell me, are you fond of fairy tales?",
  ui_story_5079_50791100_88_dialog_content = "Fairy tales? If it is your wish, I can always go read more of them...",
  ui_story_5079_50791100_89_dialog_content = "A beautiful world always conceals the cruel and brutal truth.",
  ui_story_5079_50791100_90_dialog_content = "But to confront this cruelty and emerge from it is to walk towards the light.",
  ui_story_5079_50791100_91_dialog_content = "This cycle of contradictions is the path that leads to the Truth.",
  ui_story_5079_50791100_92_dialog_content = "I understand.",
  ui_story_5079_50791100_93_dialog_content = "Where is the train stationed right now?",
  ui_story_5079_50791100_94_dialog_content = "The train? It has already gone deep into Cream Forest, and I fear it will not be returning to Folta anytime soon.",
  ui_story_5079_50791100_95_dialog_content = "Is that so? If I had known sooner, I would have taken a ride on it as well.",
  ui_story_5079_50791100_96_dialog_content = "Though he has no intention of reminiscing about the old days with me, there's no telling when we'll have another opportunity like this...",
  ui_story_5079_50791100_97_dialog_content = "Your dispute with the conductor goes back even further than my own lifetime...",
  ui_story_5079_50791100_98_dialog_content = "No, I have no right to inquire about these things... Please forgive me...",
  ui_story_5079_50791200_1_dialog_content = "<color=#e8d9bb>*footsteps*</color>",
  ui_story_5079_50791200_2_dialog_content = "Your footsteps are getting heavier. Do you need a break?",
  ui_story_5079_50791200_3_dialog_content = "I... I'm fine.",
  ui_story_5079_50791200_4_dialog_content = "If you're fine, then don't pinch your nose when you answer me...",
  ui_story_5079_50791200_5_dialog_content = "Anyway, you really seem to know your way around this place. We even managed to avoid a couple of Eclipsite mobs. Are we almost there?",
  ui_story_5079_50791200_6_dialog_content = "Of... Of course I know this place so well... It's my secret base, after all.",
  ui_story_5079_50791200_7_dialog_content = "This was where I offered the Food God all the disgusting carrots that I didn't want to eat...",
  ui_story_5079_50791200_8_dialog_content = "Naturally, I had to... clear lots of paths...",
  ui_story_5079_50791200_9_dialog_content = "Weren't you worried that the Food God would punish you for only offering the things you didn't want to eat?",
  ui_story_5079_50791200_10_dialog_content = "Not at all! My offerings were totally sincere...",
  ui_story_5079_50791200_11_dialog_content = "I prayed sincerely to the Food God... to delete carrots from every single recipe in the world!",
  ui_story_5079_50791200_12_dialog_content = "You must be pretty sincere since you yell like that even when you're so weak...",
  ui_story_5079_50791200_13_dialog_content = "You know what? I think I did something similar when I was a kid...",
  ui_story_5079_50791200_14_dialog_content = "Unfortunately, it didn't do me much good. You'd better save your strength—",
  ui_story_5079_50791200_15_dialog_content = "Hah... We're here—the cave of the Food God!",
  ui_story_5079_50791200_16_dialog_content = "*coughing* I think... I might be... allergic to carrots...",
  ui_story_5079_50791200_17_dialog_content = "I'm pretty sure this isn't just because of the carrots...",
  ui_story_5079_50791200_18_dialog_content = "With so many Eclipsites gathered here, the Darkflow is especially dense. It's normal for you to feel affected by it.",
  ui_story_5079_50791200_19_dialog_content = "Thankfully, the cave doesn't look very deep. I'll go inside and take a look while you catch your breath at the cave entrance.",
  ui_story_5079_50791200_20_dialog_content = "Hunting Stone, stay here and protect Popo.",
  ui_story_5079_50791200_21_dialog_content = "...",
  ui_story_5079_50791200_22_dialog_content = "What gives? I thought you two were best friends, so why are you worrying about me again?",
  ui_story_5079_50791200_23_dialog_content = "...",
  ui_story_5079_50791200_24_dialog_content = "Hunting Stone... I-I think you should go with her.",
  ui_story_5079_50791200_25_dialog_content = "Popo! Now's not the time to put on a brave act!",
  ui_story_5079_50791200_26_dialog_content = "I-I'm not! In my current condition, I can't control Hunting Stone... Leaving it with me would be pointless.",
  ui_story_5079_50791200_27_dialog_content = "Don't worry, I know this place like the back of my hand. It'd take Eclipsites a hundred years to find me in one of my hiding places! Heehee...",
  ui_story_5079_50791200_28_dialog_content = "... I get what you're saying now. You want me to use Hunting Stone to protect your father if he's really in there, don't you?",
  ui_story_5079_50791200_29_dialog_content = "Don't worry, I won't let anything happen to him.",
  ui_story_5079_50791200_30_dialog_content = "That's not what I meant just now... But...",
  ui_story_5079_50791200_31_dialog_content = "Please... Just come back safely, both you and my father...",
  ui_story_5079_50791200_32_dialog_content = "There's that feeling again... Why does this cave feel so familiar?",
  ui_story_5079_50791200_33_dialog_content = "It's just like when I met the head of the Ketchup Family and her advisor. But this feeling...",
  ui_story_5079_50791200_34_dialog_content = "It's so sad and painful...",
  ui_story_5079_50791200_35_dialog_content = "!",
  ui_story_5079_50791200_36_dialog_content = "I... I've been here before, but the last time... Was it because I was running away?",
  ui_story_5079_50791200_37_dialog_content = "...",
  ui_story_5079_50791200_38_dialog_content = "...",
  ui_story_5079_50791200_39_dialog_content = "*sobbing* If only...",
  ui_story_5079_50791200_40_dialog_content = "If only I had known Luminatics sooner, then maybe...",
  ui_story_5079_50791200_41_dialog_content = "Maybe mother wouldn't have been killed by Eclipsites...",
  ui_story_5079_50791200_42_dialog_content = "Sleep, Pact.",
  ui_story_5079_50791200_43_dialog_content = "But... But I want mother to hold me again...",
  ui_story_5079_50791200_44_dialog_content = "Enough! This isn't a vacation; we're running for our lives! The Eclipsites out there—",
  ui_story_5079_50791200_45_dialog_content = "... For your mother's sake, we have to do our best to survive. Do you understand?",
  ui_story_5079_50791200_46_dialog_content = "I... I don't wanna understand! I just want my mother!",
  ui_story_5079_50791200_47_dialog_content = "...",
  ui_story_5079_50791200_48_dialog_content = "Father's the worst... How could he tell me to forget about mother?",
  ui_story_5079_50791200_49_dialog_content = "I walked all the way out here, but he still hasn't come looking for me...",
  ui_story_5079_50791200_50_dialog_content = "He's the worst... How could he tell me to forget about mother?",
  ui_story_5079_50791200_51_dialog_content = "Huh? I see light in there...",
  ui_story_5079_50791200_52_dialog_content = "<color=#e8d9bb>*footsteps*</color>",
  ui_story_5079_50791200_53_dialog_content = "Is this...",
  ui_story_5079_50791200_54_dialog_content = "An idol?",
  ui_story_5079_50791200_55_dialog_content = "If there's really a god out there, then give me back my mother...",
  ui_story_5079_50791200_56_dialog_content = "No, wait... Mother said I need to be respectful when I pray to the gods. I have to be more mature about this...",
  ui_story_5079_50791200_57_dialog_content = "<color=#e8d9bb>Thud—</color>",
  ui_story_5079_50791200_58_dialog_content = "I wish for all this fighting to end. I wish for the strength to protect my family...",
  ui_story_5079_50791200_59_dialog_content = "Please grant my wish, and I will follow and worship you for the rest of my life...",
  ui_story_5079_50791200_X59_dialog_content = "I-I'll even...",
  ui_story_5079_50791200_60_dialog_content = "<color=#e8d9bb>For a long time, the little girl knelt before the idol in silent prayer.</color>",
  ui_story_5079_50791200_61_dialog_content = "<color=#e8d9bb>In the tranquil darkness, her weary heart slowly drifted into a deep sleep.</color>",
  ui_story_5079_50791200_62_dialog_content = "<color=#e8d9bb>Clatter, clatter—</color>",
  ui_story_5079_50791200_63_dialog_content = "...",
  ui_story_5079_50791200_64_dialog_content = "What do you mean?",
  ui_story_5079_50791200_65_dialog_content = "Huh? Wh-When did I fall asleep...?",
  ui_story_5079_50791200_66_dialog_content = "Pact? So this is where you've been hiding! Do you have any idea how long I've been searching for you?",
  ui_story_5079_50791200_67_dialog_content = "...",
  ui_story_5079_50791200_68_dialog_content = "!!!",
  ui_story_5079_50791200_69_dialog_content = "Wh-Why are you looking at me like that...?",
  ui_story_5079_50791200_70_dialog_content = "Pact, I need you to slowly walk towards me without looking back. Hurry!",
  ui_story_5079_50791200_71_dialog_content = "Without looking back? Is there something behind me?",
  ui_story_5079_50791200_72_dialog_content = "...",
  ui_story_5079_50791200_73_dialog_content = "Wh-What...?",
  ui_story_5079_50791200_74_dialog_content = "What... is this?",
  ui_story_5079_50791200_75_dialog_content = "Pact, I need you to slowly walk towards me. Don't be afraid, and don't look back...",
  ui_story_5079_50791200_76_dialog_content = "O-Okay... I'm coming...",
  ui_story_5079_50791200_77_dialog_content = "Graaah!",
  ui_story_5079_50791200_78_dialog_content = "What?! Of all the rotten times...",
  ui_story_5079_50791200_79_dialog_content = "Find somewhere to hide, Pact! I'll handle these monsters!!!",
  ui_story_5079_50791200_80_dialog_content = "Father... No... You don't stand a chance against Eclipsites...",
  ui_story_5079_50791200_81_dialog_content = "Graaah!",
  ui_story_5079_50791200_82_dialog_content = "No... Nooooo!!!",
  ui_story_5079_50791200_83_dialog_content = "!",
  ui_story_5079_50791200_84_dialog_content = "Graaah...",
  ui_story_5079_50791200_85_dialog_content = "Huh? That attack just now... Did I do that?",
  ui_story_5079_50791200_86_dialog_content = "This thing... This strange wheel... It's my weapon!",
  ui_story_5079_50791200_87_dialog_content = "I can use Luminatics, father! I... I can protect you now!",
  ui_story_5079_50791200_88_dialog_content = "We don't have to keep hiding anymore! ... Father? Why do you look so upset?",
  ui_story_5079_50791200_89_dialog_content = "...",
  ui_story_5079_50791200_90_dialog_content = "I see...",
  ui_story_5079_50791200_91_dialog_content = "So you were the Food God all along?",
  ui_story_5079_50791200_92_dialog_content = "Please grant my wish, and I will follow and worship you for the rest of my life...",
  ui_story_5079_50791200_93_dialog_content = "Guess I'll never be free from your shackles, huh?",
  ui_story_5079_50791200_94_dialog_content = "...",
  ui_story_5079_50791200_95_dialog_content = "Hunting Stone?",
  ui_story_5079_50791200_96_dialog_content = "...",
  ui_story_5079_50791200_97_dialog_content = "Hey, what are you doing? I didn't tell you to go over there...",
  ui_story_5079_50791200_98_dialog_content = "!",
  ui_story_5079_50791200_99_dialog_content = "They're fusing together?",
  ui_story_5079_50791200_100_dialog_content = "No... It's just returning to its original form.",
  ui_story_5079_50791200_101_dialog_content = "This is Hunting Stone's home. The place where it belongs...",
  ui_story_5079_50791200_102_dialog_content = "It wasn't following me to begin with. All this time, I was keeping it from its home...",
  ui_story_5079_50791200_103_dialog_content = "!",
  ui_story_5079_50791200_104_dialog_content = "Get it together, would you? You're just home, that's all... No need to get so excited.",
  ui_story_5079_50791200_105_dialog_content = "Or maybe it's me... Maybe I'm just incapable of having that feeling.",
  ui_story_5079_50791200_106_dialog_content = "After all, I don't have a home to go back to anymore...",
  ui_story_5079_50791200_107_dialog_content = "I never want you around, anyway. This way, everybody gets what they want.",
  ui_story_5079_50791200_108_dialog_content = "I'm going to look for Popo's father now, so...",
  ui_story_5079_50791200_109_dialog_content = "!",
  ui_story_5079_50791200_110_dialog_content = "Come along if you want, but if you decide to stay here...",
  ui_story_5079_50791200_111_dialog_content = "Then this is goodbye.",
  ui_story_5079_50791200_112_dialog_content = "It'll be for good too... You hear me?",
  ui_story_5079_50791200_113_dialog_content = "!",
  ui_story_5079_50791200_114_dialog_content = "Stop pretending already... You make it look like such a hard decision, but you're not moving at all, are you?",
  ui_story_5079_50791200_115_dialog_content = "I'm really gonna leave! See? I'm walking away...",
  ui_story_5079_50791200_116_dialog_content = "!",
  ui_story_5079_50791200_117_dialog_content = "Fine. I see you've made your decision.",
  ui_story_5079_50791200_118_dialog_content = "Goodbye, Hunting Stone.",
  ui_story_5079_50791301_1_dialog_content = "<color=#e8d9bb>*footsteps*</color>",
  ui_story_5079_50791301_2_dialog_content = "That jerk, it really did stay behind... It must be nice to have a place to call home.",
  ui_story_5079_50791301_3_dialog_content = "Could my wish be granted so easily? It feels too good to be true, and that bothers me.",
  ui_story_5079_50791301_4_dialog_content = "Just what exactly is that thing? I still have no idea...",
  ui_story_5079_50791301_5_dialog_content = "Ah, but it doesn't matter now! All that matters is that I got my wish, right?",
  ui_story_5079_50791301_6_dialog_content = "...",
  ui_story_5079_50791301_7_dialog_content = "There you are!",
  ui_story_5079_50791301_8_dialog_content = "Hey! Are you okay?",
  ui_story_5079_50791301_9_dialog_content = "Urgh...",
  ui_story_5079_50791301_10_dialog_content = "Good, your injuries don't look too serious. Come on, get up!",
  ui_story_5079_50791301_11_dialog_content = "Hey, hey! Now's not the time for a nap... Your daughter's waiting for you outside!",
  ui_story_5079_50791301_12_dialog_content = "M-My daughter...",
  ui_story_5079_50791301_13_dialog_content = "That's right! You came out here to find Popo, didn't you?",
  ui_story_5079_50791301_14_dialog_content = "P-Popo?",
  ui_story_5079_50791301_15_dialog_content = "Popo, is it really you? Oh, thank goodness... I'm so glad you're safe!",
  ui_story_5079_50791301_16_dialog_content = "I was wrong, Popo... I was too hard on you before. How could I possibly not want you?",
  ui_story_5079_50791301_17_dialog_content = "Too hard? Urgh... My head...",
  ui_story_5079_50791301_18_dialog_content = "Look, Popo! This is the greatest carrot I've ever produced in my life! One of our regulars insisted that I sell it to him, but I turned him down...",
  ui_story_5079_50791301_19_dialog_content = "*sighs* Popo still refuses to eat her carrots. What a stubborn little girl.",
  ui_story_5079_50791301_20_dialog_content = "I suppose I'll have to buy her some candy this time... But I won't be so generous the next time she turns down her food...",
  ui_story_5079_50791301_21_dialog_content = "Popo finally learned how to use Luminatics, but... I just wish she could be a little more well-mannered.",
  ui_story_5079_50791301_22_dialog_content = "I can't teach her anything... I'm such a worthless father...",
  ui_story_5079_50791301_23_dialog_content = "If only there were a noble Aurorian who could teach her, but I know no one like that at all...",
  ui_story_5079_50791301_24_dialog_content = "Your dress is covered in holes again! Why can't you just get rid of this ugly-looking thing?",
  ui_story_5079_50791301_25_dialog_content = "I... I just want to have a normal life with my normal daughter! Is that so much to ask?",
  ui_story_5079_50791301_26_dialog_content = "Think! There has to be some way to make this thing go away! I... I...",
  ui_story_5079_50791301_27_dialog_content = "Forget it... I'll never have a high-end shop for as long as I live...",
  ui_story_5079_50791301_28_dialog_content = "But at the very least, we have to live well... I'll find an arrangement that works just for you.",
  ui_story_5079_50791301_29_dialog_content = "How does that sound, Popo?",
  ui_story_5079_50791301_30_dialog_content = "Want me to accept your arrangement? Not a chance! Especially after you said I was hopeless in your letter...",
  ui_story_5079_50791301_31_dialog_content = "!",
  ui_story_5079_50791301_32_dialog_content = "Wait... What did I see just now? You're... Popo's father...",
  ui_story_5079_50791301_33_dialog_content = "Sorry, but I'm not your daughter. You'll have to save those words for her, not me.",
  ui_story_5079_50791301_34_dialog_content = "I'm... I'm just the detective who is helping Popo find you. Tell me, do you have any idea what's happening in Folta, or what's causing it?",
  ui_story_5079_50791301_35_dialog_content = "Huh? Something's happening in Folta?",
  ui_story_5079_50791301_36_dialog_content = "I have no idea what you're talking about. What's happening in our town? Wait...",
  ui_story_5079_50791301_37_dialog_content = "Aren't you... the young lady I saw on the train this morning?",
  ui_story_5079_50791301_38_dialog_content = "Please forgive me for mistaking you for my daughter! I meant no offense, miss!",
  ui_story_5079_50791301_39_dialog_content = "You said that you've been helping her? A refined noble lady such as yourself?",
  ui_story_5079_50791301_40_dialog_content = "I knew from your dignified appearance that you were a noble and high-class person!",
  ui_story_5079_50791301_41_dialog_content = "Guess my father was lying when he said that well-dressed people conduct themselves better than others!",
  ui_story_5079_50791301_42_dialog_content = "Looks like Popo remembers her father's words clearly enough...",
  ui_story_5079_50791301_43_dialog_content = "But I hardly think someone's character has anything to do with their clothes.",
  ui_story_5079_50791301_44_dialog_content = "There are plenty of dignified-looking people who do shameful things behind the scenes, just like there are people who help the underprivileged despite wearing rags themselves.",
  ui_story_5079_50791301_45_dialog_content = "Yes... I believe you're right.",
  ui_story_5079_50791301_46_dialog_content = "And on that note, being overly flattering isn't being polite. If anything, it just makes people dislike you even more...",
  ui_story_5079_50791301_47_dialog_content = "I... I'm very sorry...",
  ui_story_5079_50791301_48_dialog_content = "Urgh... Forget it. I shouldn't be teaching you manners right now...",
  ui_story_5079_50791301_49_dialog_content = "Even if you don't know what's happening in town, you must have some idea what's behind the smell of carrots in this cave, right?",
  ui_story_5079_50791301_50_dialog_content = "If we don't figure this out, your carrot shop will be shut down for good.",
  ui_story_5079_50791301_51_dialog_content = "The smell of carrots... Ah! Could it have something to do with the thing that attacked me?",
  ui_story_5079_50791301_52_dialog_content = "What \"thing\"?",
  ui_story_5079_50791301_53_dialog_content = "You might not believe me... but I think I was knocked unconscious by a gigantic carrot monster.",
  ui_story_5079_50791301_54_dialog_content = "A carrot monster? Could it be some sort of undiscovered Eclipsite?",
  ui_story_5079_50791301_55_dialog_content = "I-I'm not sure, but... this may all be my fault...",
  ui_story_5079_50791301_56_dialog_content = "After all, my daughter Popo ran away from home because of me, and I wasn't able to find her anywhere...",
  ui_story_5079_50791301_57_dialog_content = "So I started looking to folk superstitions for answers, and I spent a vast sum of money on a so-called \"supreme tribute.\"",
  ui_story_5079_50791301_58_dialog_content = "I wanted to offer it to the Food God and implore the deity to find my daughter.",
  ui_story_5079_50791301_59_dialog_content = "\"A vast sum of money\"? I had no idea you cared so much about Popo...",
  ui_story_5079_50791301_60_dialog_content = "Of course I do! She's my daughter, as well as the only family I have left in this world!",
  ui_story_5079_50791301_61_dialog_content = "The only family you have left... It sounds like you really mean that, so how did things end up like this?",
  ui_story_5079_50791301_62_dialog_content = "I... I had no idea that the supreme tribute would be absorbed by a carrot disguised as an idol!",
  ui_story_5079_50791301_63_dialog_content = "In that moment, it transformed into an enormous monster and vowed to destroy all who hate carrots.",
  ui_story_5079_50791301_64_dialog_content = "I can't remember what happened after that...",
  ui_story_5079_50791301_65_dialog_content = "Can you describe this \"supreme tribute\" to me?",
  ui_story_5079_50791301_66_dialog_content = "It was... a glowing, diamond-shaped object...",
  ui_story_5079_50791301_67_dialog_content = "Hang on a second... That sounds just like a Seed! The thing that can turn Aurorians into Eclipsites!",
  ui_story_5079_50791301_68_dialog_content = "That would explain why this carrot smell attracted all of those Eclipsites outside!",
  ui_story_5079_50791301_69_dialog_content = "If you really love your daughter, you should try harder to get along with her, and not resort to these crazy methods when things go wrong!",
  ui_story_5079_50791301_70_dialog_content = "What will you do if the consequences are irreversible? Because that may be a possibility now!",
  ui_story_5079_50791301_71_dialog_content = "Popo is such a good girl... Even though you fight all the time, she's always thinking of you...",
  ui_story_5079_50791301_72_dialog_content = "I... I know she's a good child. I know that better than anyone.",
  ui_story_5079_50791301_73_dialog_content = "But a child's attitudes need to be shaped early, and you can't praise them for everything they do. I just—",
  ui_story_5079_50791301_74_dialog_content = "You just what? That's nothing but one-sided, wishful thinking!",
  ui_story_5079_50791301_75_dialog_content = "Have you ever really listened to her feelings about this?",
  ui_story_5079_50791301_76_dialog_content = "You like carrots, so you think your child has to like them too.",
  ui_story_5079_50791301_77_dialog_content = "You want her to learn Luminatics, so she has no choice but to learn them.",
  ui_story_5079_50791301_78_dialog_content = "And now that she can use Luminatics, I bet you wish her Luminatics were as powerful and graceful as those of a Lumopolis noble! This \"love\" of yours—",
  ui_story_5079_50791301_79_dialog_content = "Don't you think it's too much for her to bear?",
  ui_story_5079_50791301_80_dialog_content = "I... Wait, Popo can use Luminatics now?",
  ui_story_5079_50791301_81_dialog_content = "...",
  ui_story_5079_50791301_82_dialog_content = "... Forget I said anything. I'm not trying to change anything here, but I just hope you'll try to be more worthy of Popo's love.",
  ui_story_5079_50791301_83_dialog_content = "Yes, she learned how to use Luminatics... and it's all because of the Eclipsites you brought here.",
  ui_story_5079_50791301_84_dialog_content = "Still... Seeds are usually only absorbed by Aurorians. How did a carrot manage to use it to become an Eclipsite?",
  ui_story_5079_50791301_85_dialog_content = "Also, I don't recall seeing any carrot monster on the way here... Wait a minute...",
  ui_story_5079_50791301_86_dialog_content = "...",
  ui_story_5079_50791301_87_dialog_content = "Aren't these the fragments of that idol I saw earlier? Why here?",
  ui_story_5079_50791301_88_dialog_content = "Oh no! Don't tell me that idol is...",
  ui_story_5079_50791301_89_dialog_content = "I... I think I can smell the source of the carrot flavoring! As if it's connected to me somehow!",
  ui_story_5079_50791301_90_dialog_content = "The smell of carrots comes from the Food God's cave! I'm certain of it now!",
  ui_story_5079_50791301_91_dialog_content = "I hear a voice too... It's telling me to come closer!",
  ui_story_5079_50791301_92_dialog_content = "Popo's in trouble!",
  ui_story_5079_50791301_93_dialog_content = "What?",
  ui_story_5079_50791301_94_dialog_content = "She's waiting just outside of the cave! We have to get back to her!",
  ui_story_5079_50791301_95_dialog_content = "Graaah!",
  ui_story_5079_50791301_96_dialog_content = "I don't have time to waste on you, now get out of my way!",
  ui_story_5079_50791401_1_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_5079_50791401_2_dialog_content = "Graah...",
  ui_story_5079_50791401_3_dialog_content = "That was the last one. We should—",
  ui_story_5079_50791401_4_dialog_content = "...",
  ui_story_5079_50791401_5_dialog_content = "Hey! We don't know what's waiting for us out there! You can't use Luminatics, so get behind me!",
  ui_story_5079_50791401_6_dialog_content = "Popo! Popo, where are you?",
  ui_story_5079_50791401_7_dialog_content = "Tsk, he's just as bad at listening as Popo. Guess they really are alike...",
  ui_story_5079_50791401_8_dialog_content = "<size=45>Popo—</size>",
  ui_story_5079_50791401_9_dialog_content = "Huh? Did I just hear father's voice?",
  ui_story_5079_50791401_10_dialog_content = "<size=45>Father! I'm over here!</size>",
  ui_story_5079_50791401_11_dialog_content = "Stay right there, Popo! I'm coming to get you!",
  ui_story_5079_50791401_12_dialog_content = "Stop! I hear something moving...",
  ui_story_5079_50791401_13_dialog_content = "Clack... Clack, clack, clack—",
  ui_story_5079_50791401_14_dialog_content = "Boom!",
  ui_story_5079_50791401_15_dialog_content = "Po...",
  ui_story_5079_50791401_16_dialog_content = "Popopo!",
  ui_story_5079_50791401_17_dialog_content = "I knew it! The carrot monster disguised itself as the idol outside!",
  ui_story_5079_50791401_18_dialog_content = "Shameless scum... It's been masquerading as the Food God and taking people's offerings for itself!",
  ui_story_5079_50791401_19_dialog_content = "Po... Popo!",
  ui_story_5079_50791401_20_dialog_content = "Wait, where's it going? Hey! Your opponent's over here!",
  ui_story_5079_50791401_21_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5079_50791401_22_dialog_content = "It totally ignores my attacks! Hey! Stop right there!",
  ui_story_5079_50791401_23_dialog_content = "Popopo!",
  ui_story_5079_50791401_24_dialog_content = "S-Stay back... Don't come any closer!",
  ui_story_5079_50791401_25_dialog_content = "T-Take this!",
  ui_story_5079_50791401_26_dialog_content = "<color=#e8d9bb>Smack—</color>",
  ui_story_5079_50791401_27_dialog_content = "Po? Popopo...",
  ui_story_5079_50791401_28_dialog_content = "Popo's Luminatics... I can't believe I'm finally seeing my daughter's powers for myself...",
  ui_story_5079_50791401_29_dialog_content = "Is this really the time to be staring in amazement? Go find a safe place to hide!",
  ui_story_5079_50791401_30_dialog_content = "But my daughter...",
  ui_story_5079_50791401_31_dialog_content = "Leave her to me!",
  ui_story_5079_50791401_32_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5079_50791401_33_dialog_content = "Popopo... Your attacks are useless against me! I have no interest in you...",
  ui_story_5079_50791401_34_dialog_content = "...",
  ui_story_5079_50791401_35_dialog_content = "But you, Popo... Even with such a wonderful name, you still despise carrots!",
  ui_story_5079_50791401_36_dialog_content = "Your hatred for them fuels my might!",
  ui_story_5079_50791401_37_dialog_content = "I was right. This thing is really after Popo!",
  ui_story_5079_50791401_38_dialog_content = "Hunting Stone! No wait, it's not—",
  ui_story_5079_50791401_39_dialog_content = "Popopo! Are you referring to this, by any chance?",
  ui_story_5079_50791401_40_dialog_content = "!",
  ui_story_5079_50791401_41_dialog_content = "Hunting Stone... Give it back to me!",
  ui_story_5079_50791401_42_dialog_content = "You useless wheel! Are you really gonna let this monster use you like that? Get over here right now...",
  ui_story_5079_50791401_43_dialog_content = "Urgh...",
  ui_story_5079_50791401_44_dialog_content = "Popopo!",
  ui_story_5079_50791401_45_dialog_content = "<color=#e8d9bb>Smack!</color>",
  ui_story_5079_50791401_46_dialog_content = "The Hunting Stone... It's not listening to me anymore?",
  ui_story_5079_50791401_47_dialog_content = "I'm ever so grateful for the weapon you gave me.",
  ui_story_5079_50791401_48_dialog_content = "But most of all, I'm grateful for you, Popo...",
  ui_story_5079_50791401_49_dialog_content = "All I need is one more bite, one last delicious morsel of hatred, and I can rule over every single piece of food in this world!",
  ui_story_5079_50791401_50_dialog_content = "Soon I will bless not just Folta, but all of Astra with the crisp and irresistible taste of carrots!",
  ui_story_5079_50791401_51_dialog_content = "Popopo!",
  ui_story_5079_50791401_52_dialog_content = "No... You can't! The world can't end up like that...",
  ui_story_5079_50791401_53_dialog_content = "\"I can't,\" you say? Popopo... I beg to differ! After all, I never would have become this powerful if you hadn't abandoned me here!",
  ui_story_5079_50791401_54_dialog_content = "Po... Po...",
  ui_story_5079_50791401_55_dialog_content = "How... How could you leave such a cute little carrot all alone here?",
  ui_story_5079_50791401_56_dialog_content = "It's dark... So dark... No nutrients... No strength...",
  ui_story_5079_50791401_57_dialog_content = "Almighty Food God, I wish to live in a world without carrots!",
  ui_story_5079_50791401_58_dialog_content = "Why do any of us have to eat something so disgusting that it shouldn't even exist?",
  ui_story_5079_50791401_59_dialog_content = "I beg of you! Please delete carrots from every single recipe known to the world!",
  ui_story_5079_50791401_60_dialog_content = "I... never should have... appeared in this world...",
  ui_story_5079_50791401_61_dialog_content = "Hated, abandoned, unneeded...",
  ui_story_5079_50791401_62_dialog_content = "O mighty Food God, please bless our family with peace and safety...",
  ui_story_5079_50791401_63_dialog_content = "Hear my plea, kind Food God! Please make that girl fall in love with me!",
  ui_story_5079_50791401_64_dialog_content = "Please accept my offerings, Food God...",
  ui_story_5079_50791401_65_dialog_content = "Food God, Food God... It's just a statue, isn't it? Why does everyone keep asking it to grant their wishes?",
  ui_story_5079_50791401_66_dialog_content = "They pray and they beg, but nothing ever happens... It doesn't deserve their worship...",
  ui_story_5079_50791401_67_dialog_content = "But I do... Because I'm real! I'm alive!",
  ui_story_5079_50791401_68_dialog_content = "Notice me! Look at me! Adore me! I'm better than that statue... because I can make your dreams come true!",
  ui_story_5079_50791401_69_dialog_content = "...",
  ui_story_5079_50791401_70_dialog_content = "Popopo!",
  ui_story_5079_50791401_71_dialog_content = "Besides, the Food God will never answer your prayers. In his place—",
  ui_story_5079_50791401_72_dialog_content = "I will enjoy your gracious offerings!",
  ui_story_5079_50791401_73_dialog_content = "O Food God, please accept this carrot as my offering. One taste and you will know exactly why I hate them so much.",
  ui_story_5079_50791401_74_dialog_content = "Yes, Popo... Keep hating them! Keep hating me! It only makes me stronger!",
  ui_story_5079_50791401_75_dialog_content = "O Food God, can you make my infuriating husband disappear?",
  ui_story_5079_50791401_76_dialog_content = "Yes, yes! I will gladly grant such a deliciously hateful wish!",
  ui_story_5079_50791401_77_dialog_content = "... Please accept this supreme tribute in exchange for finding my daughter...",
  ui_story_5079_50791401_78_dialog_content = "Yes... Yes! Do you have any idea how long I've waited for this moment?",
  ui_story_5079_50791401_79_dialog_content = "... Hmm?",
  ui_story_5079_50791401_80_dialog_content = "Po... Popopo!",
  ui_story_5079_50791401_81_dialog_content = "...",
  ui_story_5079_50791401_82_dialog_content = "So all of this happened because of me?",
  ui_story_5079_50791401_83_dialog_content = "This carrot monster... it was the carrot I left here a long time ago.",
  ui_story_5079_50791401_84_dialog_content = "Indeed, and now the time has come to pay you back in full!",
  ui_story_5079_50791401_85_dialog_content = "Ahhh—",
  ui_story_5079_50791401_86_dialog_content = "Popo!",
  ui_story_5079_50791401_87_dialog_content = "The carrot monster is using Hunting Stone's power to grow thorns on its tendrils!",
  ui_story_5079_50791401_88_dialog_content = "Tsk... If Hunting Stone hadn't become its weapon, that stupid carrot wouldn't have been this powerful!",
  ui_story_5079_50791401_89_dialog_content = "Now's not the time for you to make things even harder for me, you jerk!",
  ui_story_5079_50791401_90_dialog_content = "Let go... Let go of my daughter!",
  ui_story_5079_50791401_91_dialog_content = "Huh?",
  ui_story_5079_50791401_92_dialog_content = "Wait, what do you think you're doing? You can't even use Luminatics...",
  ui_story_5079_50791401_93_dialog_content = "If I can't use Luminatics, I'll use sticks and stones to fight.",
  ui_story_5079_50791401_94_dialog_content = "Even without those, I still have my fists!",
  ui_story_5079_50791401_95_dialog_content = "You're just asking to be killed!",
  ui_story_5079_50791401_96_dialog_content = "*coughs* That monster has my little girl. Even if it costs me my life, I have to save her!",
  ui_story_5079_50791401_97_dialog_content = "Let go of her!",
  ui_story_5079_50791401_98_dialog_content = "I told you to leave her to me... Urgh...",
  ui_story_5079_50791401_99_dialog_content = "My head... Why does this have to happen now...",
  ui_story_5079_50791401_100_dialog_content = "Who are you? Get away from my daughter!",
  ui_story_5079_50791401_101_dialog_content = "Let go of her right now, or else you'll be sorry!",
  ui_story_5079_50791401_102_dialog_content = "Get away from her right now, or else you'll be sorry!",
  ui_story_5079_50791401_103_dialog_content = "Stop, let me...",
  ui_story_5079_50791401_104_dialog_content = "Popopo!",
  ui_story_5079_50791401_105_dialog_content = "<color=#e8d9bb>Smack!</color>",
  ui_story_5079_50791401_106_dialog_content = "Urgh... Is that all you've got? Come at me, monster!",
  ui_story_5079_50791401_107_dialog_content = "<color=#e8d9bb>Smack!</color>",
  ui_story_5079_50791401_108_dialog_content = "I'm not done yet... Let go of her!",
  ui_story_5079_50791401_109_dialog_content = "<color=#e8d9bb>Smack!</color>",
  ui_story_5079_50791401_110_dialog_content = "This... This isn't over...",
  ui_story_5079_50791401_111_dialog_content = "Hurry, Popo... I'll pull the thorns away for you...",
  ui_story_5079_50791401_112_dialog_content = "<color=#e8d9bb>Stab—</color>",
  ui_story_5079_50791401_113_dialog_content = "Father... Your hands are bleeding too much! At this rate, you'll—",
  ui_story_5079_50791401_114_dialog_content = "Don't worry about me! Just go, father! This is... all my fault anyway...",
  ui_story_5079_50791401_115_dialog_content = "That's why I should—",
  ui_story_5079_50791401_116_dialog_content = "That's enough! I'm the one who bought that accursed tribute... If only I were more understanding...",
  ui_story_5079_50791401_117_dialog_content = "<color=#e8d9bb>Smack!</color>",
  ui_story_5079_50791401_118_dialog_content = "Urgh... It's finally letting go? H-Hurry, Popo...",
  ui_story_5079_50791401_119_dialog_content = "Father...",
  ui_story_5079_50791401_120_dialog_content = "I need you to turn around and walk towards the cave entrance... Don't be afraid, and don't look back...",
  ui_story_5079_50791401_121_dialog_content = "Pact, I need you to slowly walk towards me. Don't be afraid, and don't look back...",
  ui_story_5079_50791401_122_dialog_content = "H-Hurry...",
  ui_story_5079_50791401_123_dialog_content = "F-Father?",
  ui_story_5079_50791401_124_dialog_content = "This time, I'm not praying to anyone or anything else...",
  ui_story_5079_50791401_125_dialog_content = "I'll save my family with my own two hands!",
  ui_story_5079_50791501_1_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_5079_50791501_2_dialog_content = "Po...",
  ui_story_5079_50791501_3_dialog_content = "*gasping* Finally...",
  ui_story_5079_50791501_4_dialog_content = "Can you still move, Popo? You need to... hurry...",
  ui_story_5079_50791501_5_dialog_content = "The carrot monster is after you. If it manages to absorb your hatred, we won't stand a chance against it...",
  ui_story_5079_50791501_6_dialog_content = "But... But my father, he...",
  ui_story_5079_50791501_7_dialog_content = "I'll bring your father to you after I defeat that thing.",
  ui_story_5079_50791501_8_dialog_content = "But right now you need to get out of here, understand? This will be your greatest challenge yet!",
  ui_story_5079_50791501_9_dialog_content = "I... I can do it!",
  ui_story_5079_50791501_10_dialog_content = "No! There's no escaping me!",
  ui_story_5079_50791501_11_dialog_content = "Your opponent's over here!",
  ui_story_5079_50791501_12_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_5079_50791501_13_dialog_content = "Po...",
  ui_story_5079_50791501_14_dialog_content = "Tsk, still no damage huh? It feels like...",
  ui_story_5079_50791501_15_dialog_content = "Popopo... Like you're missing something, yes?",
  ui_story_5079_50791501_16_dialog_content = "If I'm not mistaken, you've used up almost all of your power, haven't you?",
  ui_story_5079_50791501_17_dialog_content = "What could you possibly do without this weapon?",
  ui_story_5079_50791501_18_dialog_content = "Tsk... Don't underestimate me, monster!",
  ui_story_5079_50791501_19_dialog_content = "<color=#e8d9bb>Swoosh! Smack—</color>",
  ui_story_5079_50791501_20_dialog_content = "...",
  ui_story_5079_50791501_21_dialog_content = "At your limit already? How disappointing!",
  ui_story_5079_50791501_22_dialog_content = "With this weapon you gave me... I'm just getting started!",
  ui_story_5079_50791501_23_dialog_content = "Urgh!",
  ui_story_5079_50791501_24_dialog_content = "So this is Hunting Stone's power... Heh, this is my first time... experiencing it for myself...",
  ui_story_5079_50791501_25_dialog_content = "I guess I should prove my power to you as well...",
  ui_story_5079_50791501_26_dialog_content = "<color=#e8d9bb>Swoosh! Smack—</color>",
  ui_story_5079_50791501_27_dialog_content = "*coughs* You're not cutting me any slack today, are you?",
  ui_story_5079_50791501_28_dialog_content = "Is this the resentment you feel towards me, Hunting Stone? Heheh...",
  ui_story_5079_50791501_29_dialog_content = "I deserve it, I suppose.",
  ui_story_5079_50791501_30_dialog_content = "I thought you refused to come with me, but you were under this carrot monster's control all along...",
  ui_story_5079_50791501_31_dialog_content = "You've been helping me this whole time, but I took your kindness for granted and constantly complained about getting rid of you...",
  ui_story_5079_50791501_32_dialog_content = "I kept telling myself that this was what I wanted... I trapped myself in a stubborn lie.",
  ui_story_5079_50791501_33_dialog_content = "And because of that... I handed you over to the enemy.",
  ui_story_5079_50791501_34_dialog_content = "<color=#e8d9bb>Swoosh! Smack—</color>",
  ui_story_5079_50791501_35_dialog_content = "Tsk, I don't know what to do anymore...",
  ui_story_5079_50791501_36_dialog_content = "Popopo! Feel the crushing sting of my empowered tendrils!",
  ui_story_5079_50791501_37_dialog_content = "Aaahhhh!",
  ui_story_5079_50791501_38_dialog_content = "...",
  ui_story_5079_50791501_39_dialog_content = "Urgh... I'm okay. After all, this isn't the first time... that I've been tied up by Hunting Stone.",
  ui_story_5079_50791501_40_dialog_content = "Good thing Popo isn't here to see this, or else she'd throw even more insults at me...",
  ui_story_5079_50791501_41_dialog_content = "He's not here to save me this time either...",
  ui_story_5079_50791501_42_dialog_content = "The only one who can help me right now...",
  ui_story_5079_50791501_43_dialog_content = "...",
  ui_story_5079_50791501_44_dialog_content = "This all feels so familiar...",
  ui_story_5079_50791501_45_dialog_content = "... Urgh.",
  ui_story_5079_50791501_46_dialog_content = "Yes, struggle and suffer... It will only make your bindings even tighter!",
  ui_story_5079_50791501_47_dialog_content = "I... I don't need you to tell me that... But...",
  ui_story_5079_50791501_48_dialog_content = "I-I don't want to lose... Hunting Stone.",
  ui_story_5079_50791501_49_dialog_content = "I don't want to lose... the right to have you at my side...",
  ui_story_5079_50791501_50_dialog_content = "...",
  ui_story_5079_50791501_51_dialog_content = "Don't you miss rolling over my face when I'm asleep?",
  ui_story_5079_50791501_52_dialog_content = "Or scaring people at the worst possible time?",
  ui_story_5079_50791501_53_dialog_content = "Don't you miss accidentally poking holes in my dress, or even doing it on purpose?",
  ui_story_5079_50791501_54_dialog_content = "If you really want to be with me again, then don't let this stupid monster control you!!!",
  ui_story_5079_50791501_55_dialog_content = "...",
  ui_story_5079_50791501_56_dialog_content = "I... belong... to Pact...",
  ui_story_5079_50791501_57_dialog_content = "But... please... remember...",
  ui_story_5079_50791501_58_dialog_content = "My strength... all comes...",
  ui_story_5079_50791501_59_dialog_content = "From... you!",
  ui_story_5079_50791501_60_dialog_content = "Hunting Stone... You can actually talk?",
  ui_story_5079_50791501_61_dialog_content = "What are these images I'm seeing?",
  ui_story_5079_50791501_62_dialog_content = "Are these... my earliest memories with Hunting Stone?",
  ui_story_5079_50791501_63_dialog_content = "Ouch... This power... It really hurts.",
  ui_story_5079_50791501_64_dialog_content = "No... Not like this! I want to use my power to fight off Eclipsites...",
  ui_story_5079_50791501_65_dialog_content = "Not to lose control in this place...",
  ui_story_5079_50791501_66_dialog_content = "Clatter, clatter...",
  ui_story_5079_50791501_67_dialog_content = "Huh? Did my power... break that idol?",
  ui_story_5079_50791501_68_dialog_content = "No... It's still there. You, on the other hand... Did it abandon you?",
  ui_story_5079_50791501_69_dialog_content = "Just like the deity abandoned us in Old Town and left us to die at the hands of Eclipsites...",
  ui_story_5079_50791501_70_dialog_content = "I lost my mother and my home... For all we know, father and I might get torn apart by Eclipsites tomorrow.",
  ui_story_5079_50791501_71_dialog_content = "And you... You have to spend the rest of your days on the cold ground, staring at the statue that once belonged to you...",
  ui_story_5079_50791501_72_dialog_content = "Does it hurt? Can you tell me... why we have to live with this kind of pain?",
  ui_story_5079_50791501_73_dialog_content = "No... That's not it...",
  ui_story_5079_50791501_74_dialog_content = "You and I... We're not the same... so stop pretending to be so miserable.",
  ui_story_5079_50791501_75_dialog_content = "Your statue's right there, so you still have a place to call home... It's fine, just use my power to return to your rightful place...",
  ui_story_5079_50791501_76_dialog_content = "<color=#e8d9bb>The girl holds the statue's fragment as though it is the last flickering ember in a world of eternal night.</color>",
  ui_story_5079_50791501_77_dialog_content = "<color=#e8d9bb>With a small but self-righteous wish, she grants it her strength...</color>",
  ui_story_5079_50791501_78_dialog_content = "...",
  ui_story_5079_50791501_79_dialog_content = "Now go. Go back home...",
  ui_story_5079_50791501_80_dialog_content = "...",
  ui_story_5079_50791501_81_dialog_content = "Are you saying... you want to stay with me? Will you... really do that?",
  ui_story_5079_50791501_82_dialog_content = "My power... It feels much calmer now. Are you helping me carry most of the burden?",
  ui_story_5079_50791501_83_dialog_content = "I feel so warm and comfortable now... Thank you... Thank you so much...",
  ui_story_5079_50791501_84_dialog_content = "I... I was the one who asked Hunting Stone to stay with me?",
  ui_story_5079_50791501_85_dialog_content = "I was the one who gave it my power...",
  ui_story_5079_50791501_86_dialog_content = "Yes... This power... It all belongs to you.",
  ui_story_5079_50791501_87_dialog_content = "You were so afraid of disappointing your father... so you refused to trust in your own strength.",
  ui_story_5079_50791501_88_dialog_content = "For that reason, you made yourself believe that this power came from me...",
  ui_story_5079_50791501_89_dialog_content = "I'm not as weak as you make me out to be... I just forgot, that's all.",
  ui_story_5079_50791501_90_dialog_content = "Perhaps, but somewhere deep in your heart, you always remember.",
  ui_story_5079_50791501_91_dialog_content = "It was not like you were not confident in your abilities, in fact, you just wanted someone to stay by your side no matter what...",
  ui_story_5079_50791501_92_dialog_content = "So I did exactly that. I was your silent companion—or at least I wanted you to feel that way about me.",
  ui_story_5079_50791501_93_dialog_content = "A silent companion should still speak up when the situation calls for it.",
  ui_story_5079_50791501_94_dialog_content = "I wish you had told me sooner that you could talk. I...",
  ui_story_5079_50791501_95_dialog_content = "I may not be the most direct person when it comes to this stuff... but I still want to know how you feel sometimes!",
  ui_story_5079_50791501_96_dialog_content = "It's because you were so honest just now that I finally chose to speak...",
  ui_story_5079_50791501_97_dialog_content = "I still remember how kind you were to me that night... I've been waiting for the time when you can finally accept me.",
  ui_story_5079_50791501_98_dialog_content = "That is why I can stand by your side and help you again!",
  ui_story_5079_50791501_99_dialog_content = "As for your power, I'll return it all to you!",
  ui_story_5079_50791501_100_dialog_content = "I know your strength and kindness better than anyone else, Pact.",
  ui_story_5079_50791501_101_dialog_content = "Now overcome the pain of your past and defeat that carrot monster!",
  ui_story_5079_50791501_102_dialog_content = "Humph, you don't have to give it back to me...",
  ui_story_5079_50791501_103_dialog_content = "After all, it's been <color=#FFB400>us</color> this entire time, hasn't it?",
  ui_story_5079_50791501_104_dialog_content = "<color=#e8d9bb>Whoosh! Crack!</color>",
  ui_story_5079_50791501_105_dialog_content = "Humph, these bindings are child's play compared to what we can really do!",
  ui_story_5079_50791501_106_dialog_content = "Why won't this weapon obey me?",
  ui_story_5079_50791501_107_dialog_content = "I still want to savor your suffering a bit more...",
  ui_story_5079_50791501_108_dialog_content = "But it seems... our time has run out. Spread, my delicious carrot aroma!",
  ui_story_5079_50791501_109_dialog_content = "Graaaaaah—",
  ui_story_5079_50791501_110_dialog_content = "What a joke. You think these small fries are enough to stop me? Heh... Guess that means you're not much stronger than them, huh?",
  ui_story_5079_50791501_111_dialog_content = "Small fry, small fry!",
  ui_story_5079_50791501_112_dialog_content = "S-Silence!",
  ui_story_5079_50791501_113_dialog_content = "As long as this thing is under my control, you have no power here!",
  ui_story_5079_50791501_114_dialog_content = "I, on the other hand, just need to consume Popo's hatred... Minions! Buy your master some more time!",
  ui_story_5079_50791501_115_dialog_content = "Graaaaaah—",
  ui_story_5079_50791501_116_dialog_content = "Running off with Hunting Stone, eh? Big mistake...",
  ui_story_5079_50791501_117_dialog_content = "As long as our hearts are one, any distance between us will only make our bond stronger.",
  ui_story_5079_50791501_118_dialog_content = "I won't let you hurt Popo...",
  ui_story_5079_50791501_119_dialog_content = "And I won't let anyone else run off with my Hunting Stone!",
  ui_story_5079_50791601_1_dialog_content = "<color=#e8d9bb>Wham, wham, wham!</color>",
  ui_story_5079_50791601_2_dialog_content = "Graaah...",
  ui_story_5079_50791601_3_dialog_content = "Outta my way, you weaklings!",
  ui_story_5079_50791601_4_dialog_content = "This can't be! How did you catch up to me so quickly?",
  ui_story_5079_50791601_5_dialog_content = "<color=#e8d9bb>Swoosh—</color>",
  ui_story_5079_50791601_6_dialog_content = "Keep your filthy tendrils away from Popo, you monster!",
  ui_story_5079_50791601_7_dialog_content = "It's... It's you...",
  ui_story_5079_50791601_8_dialog_content = "Sorry, I'm late. Don't worry, you're safe now...",
  ui_story_5079_50791601_9_dialog_content = "I... I knew you would come to save me. I never doubted it... not for a second...",
  ui_story_5079_50791601_10_dialog_content = "Sorry that my uselessness got me captured again. Is my father—",
  ui_story_5079_50791601_11_dialog_content = "Like I said, you don't have to worry anymore... Just leave everything to me.",
  ui_story_5079_50791601_12_dialog_content = "Don't... Don't you dare look at me like I'm nothing but trash!",
  ui_story_5079_50791601_13_dialog_content = "I still haven't shown you my full power!",
  ui_story_5079_50791601_14_dialog_content = "Is that so? Good. I wouldn't mind seeing it for myself either.",
  ui_story_5079_50791601_15_dialog_content = "I was ready to spare your life if you just gave me back my Hunting Stone... but not anymore.",
  ui_story_5079_50791601_16_dialog_content = "Since you insist on being this way, allow me to show you my full power too!",
  ui_story_5079_50791602_1_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_5079_50791602_2_dialog_content = "Impossible! My tendrils... Ouch... How could you...",
  ui_story_5079_50791602_3_dialog_content = "!",
  ui_story_5079_50791602_4_dialog_content = "No... Don't go!",
  ui_story_5079_50791602_5_dialog_content = "It's over for you!",
  ui_story_5079_50791602_6_dialog_content = "<color=#e8d9bb>Smack!</color>",
  ui_story_5079_50791602_7_dialog_content = "Noooo!",
  ui_story_5079_50791602_8_dialog_content = "!",
  ui_story_5079_50791602_9_dialog_content = "Huh? What are you so happy about? Cut it out already.",
  ui_story_5079_50791602_10_dialog_content = "Shouldn't you be happy too, Pact?",
  ui_story_5079_50791602_11_dialog_content = "\"I won't let anyone else run off with MY Hunting Stone!\" That's what you said, right?",
  ui_story_5079_50791602_12_dialog_content = "?",
  ui_story_5079_50791602_13_dialog_content = "You... You must've misheard me! I didn't say anything like that!",
  ui_story_5079_50791602_14_dialog_content = "Whatever you think you heard, forget about it right now!",
  ui_story_5079_50791602_15_dialog_content = "Okay...",
  ui_story_5079_50791602_16_dialog_content = "But it seems you've finally realized that you don't need me to command your power.",
  ui_story_5079_50791602_17_dialog_content = "So why bother taking me back? I can always stop following you if you really want to...",
  ui_story_5079_50791602_18_dialog_content = "Ha?",
  ui_story_5079_50791602_19_dialog_content = "The only reason things got this bad was because I handed you over to that stupid carrot monster.",
  ui_story_5079_50791602_20_dialog_content = "If an Eclipsite gets ahold of you, who knows what kind of trouble it will cause!",
  ui_story_5079_50791602_21_dialog_content = "...",
  ui_story_5079_50791602_22_dialog_content = "Your taste in choosing your prospective master is pretty awful too. I mean, a carrot? Really? You can't just go with whatever's lying around!",
  ui_story_5079_50791602_23_dialog_content = "The only person worthy of being your master is me—the great and noble Lady Pact!",
  ui_story_5079_50791602_24_dialog_content = "Understand?",
  ui_story_5079_50791602_25_dialog_content = "...",
  ui_story_5079_50791602_26_dialog_content = "You're messing with me, aren't you? Stop pretending that you can't talk!",
  ui_story_5079_50791602_27_dialog_content = "I'm not, it's just... you really do seem noble right now...",
  ui_story_5079_50791602_28_dialog_content = "Ah...",
  ui_story_5079_50791602_29_dialog_content = "<size=30>I also accept compliments like \"beautiful\" and \"adorable,\" you know...</size>",
  ui_story_5079_50791602_30_dialog_content = "I haven't lost yet!",
  ui_story_5079_50791602_31_dialog_content = "I... I will create... a perfect world for all carrots! One where no one will look down on me...",
  ui_story_5079_50791602_32_dialog_content = "A world where I'll be wanted, accepted... and allowed to live!",
  ui_story_5079_50791602_33_dialog_content = "After everything that's happened, you're still hung up on your resentment?",
  ui_story_5079_50791602_34_dialog_content = "We'll just have to put you out of your—",
  ui_story_5079_50791602_35_dialog_content = "W-<size=45>Wait!</size>",
  ui_story_5079_50791602_36_dialog_content = "?",
  ui_story_5079_50791602_37_dialog_content = "I'm sorry! I never should've left you here or said all of those mean things...",
  ui_story_5079_50791602_38_dialog_content = "My words hurt you, didn't they?",
  ui_story_5079_50791602_39_dialog_content = "It was tough, wasn't it? Spending all those days here alone...",
  ui_story_5079_50791602_40_dialog_content = "No one to talk to, no one needed you... I understand how that feels...",
  ui_story_5079_50791602_41_dialog_content = "But if you're willing to give me another chance...",
  ui_story_5079_50791602_42_dialog_content = "Could we... Could we please be friends?",
  ui_story_5079_50791602_43_dialog_content = "...",
  ui_story_5079_50791602_44_dialog_content = "I want to plant you in our garden's sunniest and most fertile patch of soil.",
  ui_story_5079_50791602_45_dialog_content = "I want you to take in all the nutrients you need to grow big and strong and become a carrot that anyone would love to eat!",
  ui_story_5079_50791602_46_dialog_content = "Uh, Popo? Offering to eat it isn't the most comforting thing to say... Wouldn't you rather it had a long, healthy life?",
  ui_story_5079_50791602_47_dialog_content = "<color=#e8d9bb>Poof!</color>",
  ui_story_5079_50791602_48_dialog_content = "Po... Popo—",
  ui_story_5079_50791602_49_dialog_content = "Does this mean... you forgive me?",
  ui_story_5079_50791602_50_dialog_content = "Popo!",
  ui_story_5079_50791602_51_dialog_content = "You know, carrots can be pretty cute too...",
  ui_story_5079_50791602_52_dialog_content = "What do you say? Should we give carrots another shot?",
  ui_story_5079_50791602_53_dialog_content = "Uh... I think I need a little more time to think about that.",
  ui_story_5079_50791602_54_dialog_content = "(So its idea of a good life is to be eaten by someone it likes...)",
  ui_story_5079_50791602_55_dialog_content = "(Well, as long as that's what gives it fulfillment...)",
  ui_story_5079_50791602_56_dialog_content = "... Popo?",
  ui_story_5079_50791602_57_dialog_content = "Father? Ahh! Try not to move! You're covered in wounds...",
  ui_story_5079_50791602_58_dialog_content = "I hardly feel a thing... Seeing you alive and well, that's all I need...",
  ui_story_5079_50791602_59_dialog_content = "This was all my fault, Popo. I never should have ordered you around so much... or forced my ideas on you...",
  ui_story_5079_50791602_60_dialog_content = "I was too obsessed with giving us an \"ideal\" family life.",
  ui_story_5079_50791602_61_dialog_content = "And I put the weight of my ambitions on your shoulders.",
  ui_story_5079_50791602_62_dialog_content = "After all, my life has never amounted to much. I've done nothing but suffer loss after loss. I even...",
  ui_story_5079_50791602_63_dialog_content = "I even lost the love of my life, your mother... It's all because I couldn't protect her...",
  ui_story_5079_50791602_64_dialog_content = "Father... All this time, you've been hiding your pain over my mother's death...",
  ui_story_5079_50791602_65_dialog_content = "And this time, I failed to protect you...",
  ui_story_5079_50791602_66_dialog_content = "When you ran away from home, I couldn't stop wondering about something—what exactly had I provided for my family?",
  ui_story_5079_50791602_67_dialog_content = "Was it nothing more than painful memories?",
  ui_story_5079_50791602_68_dialog_content = "All I wanted was to become a wealthy merchant family someday and dine at the same table as the nobles of Lumopolis.",
  ui_story_5079_50791602_69_dialog_content = "To watch you grow up and become a shining star that catches everyone's eyes, including those of the nobility...",
  ui_story_5079_50791602_70_dialog_content = "I was so blinded by my dream that I never appreciated our simple meals in our little shop or noticed the way you smiled when you ate your favorite food...",
  ui_story_5079_50791602_71_dialog_content = "Grasping those moments is what it means to be alive! To be truly happy!",
  ui_story_5079_50791602_72_dialog_content = "I—",
  ui_story_5079_50791602_73_dialog_content = "I... I want you to be happy too, father! That's why I'll keep doing my best!",
  ui_story_5079_50791602_74_dialog_content = "I'll listen to you more and stop making so much trouble for you! As long as...",
  ui_story_5079_50791602_75_dialog_content = "As long as we're together! I'll be happy for ever and ever as long as I'm with you, father!",
  ui_story_5079_50791602_76_dialog_content = "<size=30>Honestly... Don't you think you should go home before talking about all this sappy stuff?</size>",
  ui_story_5079_50791602_77_dialog_content = "<size=30>I almost said something too... This is so awkward.</size>",
  ui_story_5079_50791602_78_dialog_content = "Huh? What's in the corner of my eye?",
  ui_story_5079_50791602_79_dialog_content = "Is it raining? Good, that should wash away the smell of carrots...",
  ui_story_5079_50791602_80_dialog_content = "*sniffles* Stop crying, you dummy!",
  ui_story_5079_50791602_81_dialog_content = "Ah... I'd better not get my clothes ruined because of these tears.",
  ui_story_5079_50791602_82_dialog_content = "In the end—",
  ui_story_5079_50791602_83_dialog_content = "You realized your father's dream in the end, didn't you?",
  ui_story_5079_50791602_84_dialog_content = "Ah!",
  ui_story_5079_50791602_85_dialog_content = "Before conducting any sort of business, making yourself look dignified and presentable is the most important thing you can do.",
  ui_story_5079_50791602_86_dialog_content = "Only by doing so will rich customers give you their time and their patronage.",
  ui_story_5079_50791602_87_dialog_content = "You... When did you figure it out?",
  ui_story_5079_50791602_88_dialog_content = "When you accidentally called him \"father\" earlier, it became way too obvious.",
  ui_story_5079_50791602_89_dialog_content = "It looks like you found your answer, Pact.",
  ui_story_5079_50791602_90_dialog_content = "Don't think you're clever or anything... I just misspoke, that's all...",
  ui_story_5079_50791602_91_dialog_content = "And stop looking at me! No one's allowed to see me when I'm crying!",
  ui_story_5079_50791602_92_dialog_content = "Hey! Don't go!",
  ui_story_5079_50791602_93_dialog_content = "Huh? Uh-oh...",
  ui_story_5079_50791602_94_dialog_content = "<color=#e8d9bb>Wham—</color>",
  ui_story_5079_50791602_95_dialog_content = "...",
  ui_story_5079_50791602_96_dialog_content = "That's the second time you've run into me like that, Popo.",
  ui_story_5079_50791602_97_dialog_content = "I don't care! You can't leave yet! You can't! I... I still haven't thanked you properly!",
  ui_story_5079_50791602_98_dialog_content = "I didn't say I was leaving, I just... <size=30>didn't want either of you to see me like this.</size>",
  ui_story_5079_50791602_99_dialog_content = "Besides, you don't have to thank me for anything... I was just doing what I was supposed to do.",
  ui_story_5079_50791602_100_dialog_content = "Yeah, right! You just don't want to admit that you're a good person! But now I know you're one of the kindest people out there!",
  ui_story_5079_50791602_101_dialog_content = "Thank you for helping me make up with my father, and thank you...",
  ui_story_5079_50791602_102_dialog_content = "For showing me... that I'm very much loved!",
  ui_story_5079_50791602_103_dialog_content = "I'm... I'm gonna do my best!",
  ui_story_5079_50791602_104_dialog_content = "From now on, I'm gonna work hard to become a strong and kind person, just like you!",
  ui_story_5079_50791602_105_dialog_content = "Me? Heh... I'm not exactly worthy of being called a role model.",
  ui_story_5079_50791602_106_dialog_content = "Just keep moving forward and you'll be fine, Popo.",
  ui_story_5079_50791602_107_dialog_content = "Keep moving forward, follow your heart, and never look back.",
  ui_story_5079_50791602_108_dialog_content = "Do that, and you'll meet all kinds of wonderful people—people who respect you, people who laugh with you, and people who fill you with warmth throughout your journey.",
  ui_story_5079_50791602_109_dialog_content = "If you ever lose your way, just lift your head...",
  ui_story_5079_50791602_110_dialog_content = "Take a long look at the star-studded sky, and you'll find the answers you need, just like I did.",
  ui_story_5079_50791602_111_dialog_content = "Because...",
  ui_story_5079_50791602_112_dialog_content = "I am you, Popo.",
  ui_story_5079_50791602_113_dialog_content = "Wait... Are you the future me?",
  ui_story_5079_50791602_114_dialog_content = "I really hope I can be as amazing as you someday!",
  ui_story_5079_50791602_115_dialog_content = "You will, trust me.",
  ui_story_5079_50791602_116_dialog_content = "Ah, father's telling me to come home now...",
  ui_story_5079_50791602_117_dialog_content = "No matter where you go, don't forget about me, okay?",
  ui_story_5079_50791602_118_dialog_content = "Popo...",
  ui_story_5079_50791602_119_dialog_content = "Once I remember something, I'll never forget it.",
  ui_story_5079_50791602_120_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50791602_121_dialog_content = "It's time for us to get going.",
  ui_story_5079_50791602_122_dialog_content = "Yeah, you're right, but I really want to know...",
  ui_story_5079_50791602_123_dialog_content = "In the future, will she have a happier childhood than me here in Folta?",
  ui_story_5079_50791602_124_dialog_content = "Will she be able to smile for all the times I couldn't?",
  ui_story_5079_50791602_125_dialog_content = "Will she never have to feel the same anger or sadness that I felt?",
  ui_story_5079_50791602_126_dialog_content = "Will she... be able to spend her life without confronting a painful childhood?",
  ui_story_5079_50791602_127_dialog_content = "... I'm sure she'll be fine. After all, you've already healed so many others, including yourself.",
  ui_story_5079_50791602_128_dialog_content = "Remember, you're the kind and noble Lady Pact.",
  ui_story_5079_50791602_129_dialog_content = "You found your way a long time ago. It's just like you said—",
  ui_story_5079_50791602_130_dialog_content = "\"Keep moving forward, follow your heart, and never look back.\"",
  ui_story_5079_50791602_131_dialog_content = "Popo's future is full of so many wonderful possibilities, and so is yours!",
  ui_story_5079_50791602_132_dialog_content = "Just as I thought, you only talk when it's time to give a big speech, and then there's no stopping you.",
  ui_story_5079_50791602_133_dialog_content = "Don't get too sentimental. My problems aren't fixed just because you said a few nice words.",
  ui_story_5079_50791602_134_dialog_content = "Now that I think about it, you really do remind me of my Hunting Stone sometimes, PlayerName.",
  ui_story_5079_50791602_135_dialog_content = "Huh? When did you figure it out?",
  ui_story_5079_50791602_136_dialog_content = "It wasn't hard. All I had to do was put together your little performance and your habit of giving pep talks.",
  ui_story_5079_50791602_137_dialog_content = "This is the wisdom I gained from the rules. Do you want me to explain them to you?",
  ui_story_5079_50791602_138_dialog_content = "...",
  ui_story_5079_50791602_139_dialog_content = "I told you already: stop pretending that you can't talk! It makes things look awkward!",
  ui_story_5079_50791602_140_dialog_content = "I... I actually agree with you on a lot of things!",
